import { useState } from 'react';
import { Flag, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { useAuth } from '../context/AuthContext';
import api from '../../lib/api';
import { Button } from './ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from './ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from './ui/select';
import { Textarea } from './ui/textarea';

type ReportTargetType = 'list' | 'comment' | 'user';

type ReportButtonProps = {
  targetId: string;
  targetType: ReportTargetType;
  buttonLabel?: string;
  buttonClassName?: string;
};

const REASON_OPTIONS: Record<ReportTargetType, Array<{ value: string; label: string }>> = {
  list: [
    { value: 'Spam', label: 'Spam' },
    { value: 'Contenido Ofensivo', label: 'Contenido Ofensivo' },
    { value: 'Información Falsa', label: 'Información Falsa' },
    { value: 'Otros', label: 'Otros' },
  ],
  comment: [
    { value: 'Spam', label: 'Spam' },
    { value: 'Contenido Ofensivo', label: 'Contenido Ofensivo' },
    { value: 'Información Falsa', label: 'Información Falsa' },
    { value: 'Otros', label: 'Otros' },
  ],
  user: [
    { value: 'Nombre Ofensivo', label: 'Nombre de Usuario Ofensivo' },
    { value: 'Imagen Inadecuada', label: 'Imagen de Perfil Inadecuada' },
    { value: 'Se hace pasar por otra persona', label: 'Se hace pasar por otra persona' },
    { value: 'Otros', label: 'Otros' },
  ],
};

export function ReportButton({
  targetId,
  targetType,
  buttonLabel = 'Reportar',
  buttonClassName = '',
}: ReportButtonProps) {
  const { user } = useAuth();
  const [open, setOpen] = useState(false);
  const [reason, setReason] = useState('');
  const [description, setDescription] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  if (!user) return null;

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();

    if (!reason) {
      toast.error('Selecciona un motivo para continuar.');
      return;
    }

    try {
      setIsSubmitting(true);
      await api.post('/api/reports', {
        targetId,
        targetType,
        reason,
        description,
      });

      toast.success('Reporte enviado correctamente.');
      setOpen(false);
      setReason('');
      setDescription('');
    } catch (error: any) {
      const backendMessage = error?.response?.data?.error;
      toast.error(backendMessage || 'No se pudo enviar el reporte.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const getTargetTypeLabel = () => {
    if (targetType === 'user') return 'usuario';
    if (targetType === 'list') return 'lista';
    if (targetType === 'comment') return 'comentario';
    return 'contenido';
  };

  const reasons = REASON_OPTIONS[targetType];

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <button
          type="button"
          className={buttonClassName || 'inline-flex items-center gap-2 text-[#90a1b9] hover:text-[#ff8a8c] transition-colors text-[14px]'}
        >
          <Flag size={16} />
          {buttonLabel}
        </button>
      </DialogTrigger>

      <DialogContent className="bg-[#0f172b] border-[#1d293d] text-white">
        <DialogHeader>
          <DialogTitle>Reportar {getTargetTypeLabel()}</DialogTitle>
          <DialogDescription className="text-[#90a1b9]">
            Tu reporte sera revisado por el equipo de moderacion.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <p className="mb-2 text-sm text-[#cad5e2]">Motivo del reporte</p>
            <Select value={reason} onValueChange={setReason}>
              <SelectTrigger className="border-[#314158] bg-[rgba(2,6,24,0.5)] text-white">
                <SelectValue placeholder="Selecciona un motivo" />
              </SelectTrigger>
              <SelectContent className="bg-[#0f172b] border-[#314158] text-white">
                {reasons.map((item) => (
                  <SelectItem key={item.value} value={item.value}>
                    {item.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <div className="flex justify-between items-end mb-2">
              <p className="text-sm text-[#cad5e2]">Descripcion adicional (opcional)</p>
              <span className="text-xs text-[#62748e]">{description.length}/500</span>
            </div>
            <Textarea
              value={description}
              onChange={(event) => setDescription(event.target.value)}
              placeholder="Anade detalles para ayudar a moderacion..."
              maxLength={500}
              className="min-h-24 border-[#314158] bg-[rgba(2,6,24,0.5)] text-white placeholder:text-[#62748e] resize-none"
            />
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              className="border-[#314158] bg-transparent text-[#cad5e2] hover:bg-[#1d293d]"
              onClick={() => setOpen(false)}
              disabled={isSubmitting}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isSubmitting || !reason}>
              {isSubmitting ? (
                <>
                  <Loader2 className="size-4 animate-spin" />
                  Enviando...
                </>
              ) : (
                'Enviar reporte'
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useMemo } from "react";
import {
  Calendar,
  Clock,
  ChevronLeft,
  ChevronRight,
  X,
  Users,
  Check,
  Bell,
  Gamepad2,
  ArrowLeft,
  PartyPopper,
  Loader2,
} from "lucide-react";
import { toast } from "sonner";
import { createGamingSession } from "../../lib/api";

export interface SessionFriend {
  steamId: string;
  username: string;
  avatar: string;
  status: number;
  participantStatus?: 'invited' | 'accepted' | 'declined';
}

export interface SessionGame {
  appid: number;
  name: string;
  headerImage?: string;
}

export interface ScheduledSession {
  id: string;
  game: SessionGame;
  date: string;
  time: string;
  friends: SessionFriend[];
  confirmed: boolean;
  myParticipantStatus?: 'invited' | 'accepted' | 'declined';
  isHost?: boolean;
}

interface Props {
  game: SessionGame;
  selectedFriends: SessionFriend[];
  onClose: () => void;
  onConfirm: () => Promise<void> | void;
  existingSessions: ScheduledSession[];
}

const HOURS = [
  "09:00",
  "10:00",
  "11:00",
  "12:00",
  "13:00",
  "14:00",
  "15:00",
  "16:00",
  "17:00",
  "18:00",
  "19:00",
  "20:00",
  "21:00",
  "22:00",
  "23:00",
  "00:00",
];

const DAYS_ES = ["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"];
const MONTHS_ES = [
  "Enero",
  "Febrero",
  "Marzo",
  "Abril",
  "Mayo",
  "Junio",
  "Julio",
  "Agosto",
  "Septiembre",
  "Octubre",
  "Noviembre",
  "Diciembre",
];

function buildScheduledAt(dateStr: string, timeStr: string) {
  const [year, month, day] = dateStr.split("-").map(Number);
  const [hours, minutes] = timeStr.split(":").map(Number);
  const localDate = new Date(year, month - 1, day, hours, minutes, 0, 0);
  return localDate.toISOString();
}

export function SessionBooking({
  game,
  selectedFriends,
  onClose,
  onConfirm,
  existingSessions,
}: Props) {
  const today = new Date();
  const [currentMonth, setCurrentMonth] = useState(today.getMonth());
  const [currentYear, setCurrentYear] = useState(today.getFullYear());
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [selectedTime, setSelectedTime] = useState<string | null>(null);
  const [step, setStep] = useState<"date" | "time" | "confirm">("date");
  const [notifyFriends, setNotifyFriends] = useState(true);
  const [saving, setSaving] = useState(false);

  const calendarDays = useMemo(() => {
    const firstDay = new Date(currentYear, currentMonth, 1);
    const lastDay = new Date(currentYear, currentMonth + 1, 0);
    const startDayOfWeek = (firstDay.getDay() + 6) % 7;

    const days: {
      date: number;
      month: number;
      year: number;
      isCurrentMonth: boolean;
      isToday: boolean;
      isPast: boolean;
      dateStr: string;
    }[] = [];

    const prevMonthLast = new Date(currentYear, currentMonth, 0).getDate();
    for (let i = startDayOfWeek - 1; i >= 0; i--) {
      const d = prevMonthLast - i;
      const m = currentMonth === 0 ? 11 : currentMonth - 1;
      const y = currentMonth === 0 ? currentYear - 1 : currentYear;
      days.push({
        date: d,
        month: m,
        year: y,
        isCurrentMonth: false,
        isToday: false,
        isPast: true,
        dateStr: `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`,
      });
    }

    for (let d = 1; d <= lastDay.getDate(); d++) {
      const dateObj = new Date(currentYear, currentMonth, d);
      const isToday = dateObj.toDateString() === today.toDateString();
      const isPast =
        dateObj < new Date(today.getFullYear(), today.getMonth(), today.getDate());
      const dateStr = `${currentYear}-${String(currentMonth + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
      days.push({
        date: d,
        month: currentMonth,
        year: currentYear,
        isCurrentMonth: true,
        isToday,
        isPast,
        dateStr,
      });
    }

    const remaining = 42 - days.length;
    for (let d = 1; d <= remaining; d++) {
      const m = currentMonth === 11 ? 0 : currentMonth + 1;
      const y = currentMonth === 11 ? currentYear + 1 : currentYear;
      days.push({
        date: d,
        month: m,
        year: y,
        isCurrentMonth: false,
        isToday: false,
        isPast: false,
        dateStr: `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`,
      });
    }

    return days;
  }, [currentMonth, currentYear]);

  const hasSessionOnDate = (dateStr: string) => {
    return existingSessions.some((s) => s.date === dateStr);
  };

  const prevMonth = () => {
    if (currentMonth === 0) {
      setCurrentMonth(11);
      setCurrentYear(currentYear - 1);
    } else {
      setCurrentMonth(currentMonth - 1);
    }
  };

  const nextMonth = () => {
    if (currentMonth === 11) {
      setCurrentMonth(0);
      setCurrentYear(currentYear + 1);
    } else {
      setCurrentMonth(currentMonth + 1);
    }
  };

  const handleDateSelect = (dateStr: string, isPast: boolean) => {
    if (isPast) return;
    setSelectedDate(dateStr);
    setStep("time");
  };

  const handleTimeSelect = (time: string) => {
    setSelectedTime(time);
    setStep("confirm");
  };

  const handleConfirm = async () => {
    if (!selectedDate || !selectedTime) return;
    if (selectedFriends.length === 0) {
      toast.error("Selecciona al menos un amigo para crear la sesión.");
      return;
    }

    setSaving(true);

    try {
      const payload = {
        game: {
          appid: game.appid,
          name: game.name,
          headerImage:
            game.headerImage ||
            `https://cdn.cloudflare.steamstatic.com/steam/apps/${game.appid}/header.jpg`,
        },
        date: selectedDate,
        time: selectedTime,
        scheduledAt: buildScheduledAt(selectedDate, selectedTime),
        participants: selectedFriends.map((friend) => ({
          steamId: friend.steamId,
          username: friend.username,
          avatar: friend.avatar,
        })),
        notes: "",
        notifyFriends,
      };

      await createGamingSession(payload);
      await onConfirm();

      toast.success(
        `Sesión programada: ${game.name} el ${formatDateDisplay(selectedDate)} a las ${selectedTime}`,
        { duration: 5000 },
      );

      onClose();
    } catch (error: any) {
      console.error("Error creating gaming session:", error);
      toast.error(
        error?.response?.data?.error || "No se pudo crear la sesión.",
      );
    } finally {
      setSaving(false);
    }
  };

  const formatDateDisplay = (dateStr: string) => {
    const [y, m, d] = dateStr.split("-").map(Number);
    const date = new Date(y, m - 1, d);
    const dayName = DAYS_ES[(date.getDay() + 6) % 7];
    return `${dayName} ${d} de ${MONTHS_ES[m - 1]}`;
  };

  const isPopularHour = (time: string) => {
    const hour = parseInt(time.split(":")[0]);
    return hour >= 18 && hour <= 23;
  };

  const gameImage =
    game.headerImage ||
    `https://cdn.cloudflare.steamstatic.com/steam/apps/${game.appid}/header.jpg`;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-black/70 backdrop-blur-sm"
        onClick={saving ? undefined : onClose}
      />

      <div className="relative bg-slate-900 border border-slate-700 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-300">
        <div className="relative p-5 pb-4 border-b border-slate-800">
          <div className="absolute inset-0 bg-gradient-to-r from-blue-900/30 via-indigo-900/20 to-purple-900/30" />
          <div className="relative flex items-center justify-between">
            <div className="flex items-center gap-3">
              {step !== "date" && (
                <button
                  onClick={() => setStep(step === "confirm" ? "time" : "date")}
                  className="p-1.5 hover:bg-slate-800 rounded-lg transition-colors text-slate-400 hover:text-white"
                  disabled={saving}
                >
                  <ArrowLeft size={18} />
                </button>
              )}
              <div>
                <h2 className="text-lg font-bold text-white flex items-center gap-2">
                  <Calendar size={20} className="text-blue-400" />
                  Reservar Sesión
                </h2>
                <p className="text-xs text-slate-400 mt-0.5">
                  {step === "date" && "Elige una fecha"}
                  {step === "time" && "Elige una hora"}
                  {step === "confirm" && "Confirma la sesión"}
                </p>
              </div>
            </div>

            <button
              onClick={onClose}
              disabled={saving}
              className="p-2 hover:bg-slate-800 rounded-xl transition-colors text-slate-400 hover:text-white disabled:opacity-50"
            >
              <X size={18} />
            </button>
          </div>

          <div className="relative flex items-center gap-3 mt-4 bg-slate-800/60 rounded-xl p-3">
            <img
              src={gameImage}
              alt={game.name}
              className="w-16 h-10 rounded-lg object-cover"
              onError={(e) => {
                (e.target as HTMLImageElement).src =
                  "https://via.placeholder.com/150x100?text=Game";
              }}
            />
            <div className="flex-1 min-w-0">
              <h3 className="text-sm font-bold text-white truncate">{game.name}</h3>
              <div className="flex items-center gap-1 text-[10px] text-slate-500">
                <Users size={10} />
                <span>Tú + {selectedFriends.length} amigos</span>
              </div>
            </div>

            <div className="flex -space-x-2">
              {selectedFriends.slice(0, 3).map((f) => (
                <img
                  key={f.steamId}
                  src={f.avatar}
                  alt={f.username}
                  className="w-7 h-7 rounded-full border-2 border-slate-800 object-cover"
                  title={f.username}
                />
              ))}
              {selectedFriends.length > 3 && (
                <div className="w-7 h-7 rounded-full border-2 border-slate-800 bg-slate-700 flex items-center justify-center text-[9px] text-slate-300 font-bold">
                  +{selectedFriends.length - 3}
                </div>
              )}
            </div>
          </div>

          <div className="relative flex items-center justify-center gap-2 mt-4">
            {["date", "time", "confirm"].map((s, i) => (
              <div key={s} className="flex items-center gap-2">
                <div
                  className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold transition-all ${
                    step === s
                      ? "bg-blue-600 text-white scale-110"
                      : ["date", "time", "confirm"].indexOf(step) > i
                        ? "bg-emerald-600 text-white"
                        : "bg-slate-800 text-slate-500"
                  }`}
                >
                  {["date", "time", "confirm"].indexOf(step) > i ? (
                    <Check size={12} />
                  ) : (
                    i + 1
                  )}
                </div>
                {i < 2 && (
                  <div
                    className={`w-12 h-0.5 rounded-full transition-colors ${
                      ["date", "time", "confirm"].indexOf(step) > i
                        ? "bg-emerald-600"
                        : "bg-slate-800"
                    }`}
                  />
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="p-5">
          {step === "date" && (
            <div className="animate-in fade-in duration-300">
              <div className="flex items-center justify-between mb-4">
                <button
                  onClick={prevMonth}
                  className="p-2 hover:bg-slate-800 rounded-lg transition-colors text-slate-400 hover:text-white"
                  disabled={saving}
                >
                  <ChevronLeft size={18} />
                </button>
                <h3 className="text-sm font-bold text-white">
                  {MONTHS_ES[currentMonth]} {currentYear}
                </h3>
                <button
                  onClick={nextMonth}
                  className="p-2 hover:bg-slate-800 rounded-lg transition-colors text-slate-400 hover:text-white"
                  disabled={saving}
                >
                  <ChevronRight size={18} />
                </button>
              </div>

              <div className="grid grid-cols-7 gap-1 mb-2">
                {DAYS_ES.map((day) => (
                  <div
                    key={day}
                    className="text-center text-[10px] font-bold text-slate-500 uppercase tracking-wider py-1"
                  >
                    {day}
                  </div>
                ))}
              </div>

              <div className="grid grid-cols-7 gap-1">
                {calendarDays.map((day, i) => {
                  const isSelected = selectedDate === day.dateStr;
                  const hasSession = hasSessionOnDate(day.dateStr);

                  return (
                    <button
                      key={i}
                      onClick={() => handleDateSelect(day.dateStr, day.isPast)}
                      disabled={day.isPast || saving}
                      className={`relative h-10 rounded-xl text-sm font-medium transition-all duration-200 ${
                        isSelected
                          ? "bg-blue-600 text-white shadow-lg shadow-blue-900/30 scale-105"
                          : day.isToday
                            ? "bg-blue-600/20 text-blue-400 border border-blue-500/40 hover:bg-blue-600/30"
                            : day.isPast
                              ? "text-slate-700 cursor-not-allowed"
                              : day.isCurrentMonth
                                ? "text-slate-300 hover:bg-slate-800 hover:text-white"
                                : "text-slate-600 hover:bg-slate-800/50"
                      }`}
                    >
                      {day.date}
                      {day.isToday && (
                        <div className="absolute bottom-1 left-1/2 -translate-x-1/2 w-1 h-1 rounded-full bg-blue-400" />
                      )}
                      {hasSession && !isSelected && (
                        <div className="absolute top-1 right-1 w-1.5 h-1.5 rounded-full bg-emerald-400" />
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {step === "time" && selectedDate && (
            <div className="animate-in fade-in slide-in-from-right-4 duration-300">
              <p className="text-sm text-slate-400 mb-4">
                📅 <span className="text-white font-medium">{formatDateDisplay(selectedDate)}</span> — ¿A qué hora?
              </p>

              <div className="grid grid-cols-4 gap-2">
                {HOURS.map((time) => {
                  const popular = isPopularHour(time);
                  const isSelected = selectedTime === time;

                  return (
                    <button
                      key={time}
                      onClick={() => handleTimeSelect(time)}
                      disabled={saving}
                      className={`relative py-3 rounded-xl text-sm font-medium transition-all duration-200 ${
                        isSelected
                          ? "bg-blue-600 text-white shadow-lg shadow-blue-900/30 scale-105"
                          : "bg-slate-800/60 text-slate-300 hover:bg-slate-700 hover:text-white border border-slate-700/50 hover:border-slate-600"
                      }`}
                    >
                      <Clock size={12} className="inline mr-1 opacity-50" />
                      {time}
                      {popular && !isSelected && (
                        <div className="absolute -top-1 -right-1 w-3 h-3 rounded-full bg-amber-500 flex items-center justify-center">
                          <span className="text-[6px] text-black font-bold">🔥</span>
                        </div>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {step === "confirm" && selectedDate && selectedTime && (
            <div className="animate-in fade-in slide-in-from-right-4 duration-300 space-y-5">
              <div className="bg-gradient-to-br from-blue-900/30 to-indigo-900/20 border border-blue-500/20 rounded-2xl p-5">
                <div className="flex items-start gap-4">
                  <img
                    src={gameImage}
                    alt={game.name}
                    className="w-24 h-14 rounded-xl object-cover shadow-lg"
                  />
                  <div className="flex-1">
                    <h3 className="text-base font-bold text-white">{game.name}</h3>
                    <div className="flex flex-col gap-1 mt-2">
                      <span className="text-sm text-slate-300 flex items-center gap-2">
                        <Calendar size={14} className="text-blue-400" />
                        {formatDateDisplay(selectedDate)}
                      </span>
                      <span className="text-sm text-slate-300 flex items-center gap-2">
                        <Clock size={14} className="text-purple-400" />
                        {selectedTime}h
                      </span>
                    </div>
                  </div>
                </div>
              </div>

              <div>
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">
                  Participantes ({selectedFriends.length + 1})
                </h4>
                <div className="space-y-2">
                  <div className="flex items-center gap-3 bg-slate-800/40 rounded-xl p-2.5">
                    <div className="w-8 h-8 rounded-full bg-blue-600 flex items-center justify-center text-white text-xs font-bold">
                      Yo
                    </div>
                    <span className="text-sm text-white font-medium flex-1">Tú</span>
                    <span className="text-[10px] bg-emerald-500/10 text-emerald-400 px-2 py-0.5 rounded-full border border-emerald-500/20">
                      Organizador
                    </span>
                  </div>

                  {selectedFriends.map((f) => (
                    <div
                      key={f.steamId}
                      className="flex items-center gap-3 bg-slate-800/40 rounded-xl p-2.5"
                    >
                      <img
                        src={f.avatar}
                        alt={f.username}
                        className="w-8 h-8 rounded-full object-cover"
                      />
                      <span className="text-sm text-slate-300 flex-1">
                        {f.username}
                      </span>
                      <span
                        className={`text-[10px] px-2 py-0.5 rounded-full border ${
                          f.status > 0
                            ? "bg-green-500/10 text-green-400 border-green-500/20"
                            : "bg-slate-700/50 text-slate-500 border-slate-600/30"
                        }`}
                      >
                        {f.status > 0 ? "Online" : "Offline"}
                      </span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="flex items-center justify-between bg-slate-800/40 rounded-xl p-3">
                <div className="flex items-center gap-3">
                  <Bell size={16} className="text-amber-400" />
                  <div>
                    <p className="text-sm text-white font-medium">Notificar amigos</p>
                    <p className="text-[10px] text-slate-500">
                      Envía una invitación visual a todos los participantes
                    </p>
                  </div>
                </div>

                <button
                  onClick={() => setNotifyFriends(!notifyFriends)}
                  disabled={saving}
                  className={`w-11 h-6 rounded-full transition-colors relative ${
                    notifyFriends ? "bg-blue-600" : "bg-slate-700"
                  }`}
                >
                  <div
                    className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow transition-transform ${
                      notifyFriends ? "left-6" : "left-1"
                    }`}
                  />
                </button>
              </div>

              <button
                onClick={handleConfirm}
                disabled={saving}
                className="w-full py-3.5 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold rounded-xl transition-all shadow-lg shadow-blue-900/30 flex items-center justify-center gap-2 active:scale-[0.98] disabled:opacity-60"
              >
                {saving ? (
                  <>
                    <Loader2 size={18} className="animate-spin" />
                    Guardando...
                  </>
                ) : (
                  <>
                    <Gamepad2 size={18} />
                    Confirmar Sesión
                  </>
                )}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export function UpcomingSessions({
  sessions,
  onRemove,
  onLeave,
  currentUserSteamId,
}: {
  sessions: ScheduledSession[];
  onRemove: (id: string) => void;
  onLeave?: (id: string) => void;
  currentUserSteamId?: string;
}) {
  if (sessions.length === 0) return null;

  const formatDate = (dateStr: string) => {
    const [y, m, d] = dateStr.split("-").map(Number);
    const date = new Date(y, m - 1, d);
    const dayName = DAYS_ES[(date.getDay() + 6) % 7];
    return `${dayName} ${d} ${MONTHS_ES[m - 1].slice(0, 3)}`;
  };

  return (
    <div className="bg-slate-900/80 backdrop-blur border border-slate-800 rounded-3xl p-6 shadow-xl mt-8">
      <h3 className="text-lg font-bold text-white mb-5 flex items-center gap-2">
        <PartyPopper className="text-amber-400" size={20} />
        Sesiones Programadas
      </h3>

      <div className="space-y-3">
        {sessions.map((session) => (
          <div
            key={session.id}
            className="flex items-center gap-4 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50"
          >
            <img
              src={
                session.game.headerImage ||
                `https://cdn.cloudflare.steamstatic.com/steam/apps/${session.game.appid}/header.jpg`
              }
              alt={session.game.name}
              className="w-20 h-12 rounded-lg object-cover shadow-md"
            />
            <div className="flex-1 min-w-0">
              <h4 className="text-sm font-bold text-white truncate">
                {session.game.name}
              </h4>
              <div className="flex items-center gap-3 mt-1">
                <span className="text-xs text-slate-400 flex items-center gap-1">
                  <Calendar size={11} className="text-blue-400" />
                  {formatDate(session.date)}
                </span>
                <span className="text-xs text-slate-400 flex items-center gap-1">
                  <Clock size={11} className="text-purple-400" />
                  {session.time}
                </span>
              </div>
            </div>

            <div className="flex -space-x-2 mr-2">
              {session.friends.slice(0, 3).map((f) => (
                <img
                  key={f.steamId}
                  src={f.avatar}
                  alt={f.username}
                  className="w-7 h-7 rounded-full border-2 border-slate-800 object-cover"
                  title={f.username}
                />
              ))}
            </div>

            {/* Status badge — reflects real participant response */}
            {session.myParticipantStatus === 'declined' ? (
              <span className="text-[10px] bg-red-500/10 text-red-400 px-2.5 py-1 rounded-full border border-red-500/20 font-bold whitespace-nowrap">
                <X size={10} className="inline mr-0.5" />
                Rechazada
              </span>
            ) : session.myParticipantStatus === 'accepted' ? (
              <span className="text-[10px] bg-emerald-500/10 text-emerald-400 px-2.5 py-1 rounded-full border border-emerald-500/20 font-bold whitespace-nowrap">
                <Check size={10} className="inline mr-0.5" />
                Confirmada
              </span>
            ) : session.myParticipantStatus === 'invited' ? (
              <span className="text-[10px] bg-amber-500/10 text-amber-400 px-2.5 py-1 rounded-full border border-amber-500/20 font-bold whitespace-nowrap">
                Pendiente
              </span>
            ) : (
              // Host view — show overall session status
              <span className="text-[10px] bg-emerald-500/10 text-emerald-400 px-2.5 py-1 rounded-full border border-emerald-500/20 font-bold whitespace-nowrap">
                <Check size={10} className="inline mr-0.5" />
                Programada
              </span>
            )}

            {/* Eliminar botón de cancelar/abandonar para sesiones confirmadas */}
            {/* Si quieres mostrar el botón de abandonar/cancelar en otros estados, puedes añadir lógica aquí */}
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "motion/react";
import { Bot, X, Send, Sparkles, Eye, Maximize2, Minimize2, Monitor, Image as ImageIcon, XCircle } from "lucide-react";
import api from "../../../lib/api";
import { useAuth } from "../../context/AuthContext";

interface Message {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  hasScreenContext?: boolean;
  image?: string;
}

export function AssistantModal() {
  const [isOpen, setIsOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'assistant', text: '¡Hola! Soy tu asistente de juegos SteaMate. Usa el botón de ojo para compartir lo que ves en pantalla. ¿En qué te ayudo?' }
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [hasScreenContext, setHasScreenContext] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { user } = useAuth();

  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen, loading]);

  // Capture screen context as text - UNIVERSAL para TODAS las páginas de la app
  const captureScreenContext = (): string => {
    const context: string[] = [];
    const path = window.location.pathname;

    // ========== INFORMACIÓN BÁSICA (todas las páginas) ==========
    context.push(`Ubicación: ${path}`);
    context.push(`Título: ${document.title}`);

    const mainHeading = document.querySelector('h1');
    if (mainHeading?.textContent?.trim()) {
      context.push(`\nPágina: ${mainHeading.textContent.trim()}`);
    }

    const subtitle = document.querySelector('h1 + p');
    if (subtitle?.textContent?.trim()) {
      context.push(`Subtítulo: ${subtitle.textContent.trim()}`);
    }

    // ========== TABS/FILTROS ACTIVOS ==========
    const activeTabs = Array.from(
      document.querySelectorAll('[class*="bg-[#155dfc]"], [class*="bg-[#2b7fff]"], button[class*="shadow"]')
    )
      .map(el => el.textContent?.trim())
      .filter(text => text && text.length > 0 && text.length < 50);

    if (activeTabs.length > 0) {
      context.push(`\nTabs/Filtros activos: ${[...new Set(activeTabs)].join(', ')}`);
    }

    // ========== CATEGORÍAS/CHIPS ==========
    const chips = Array.from(document.querySelectorAll('[class*="rounded-full"]'))
      .map(chip => chip.textContent?.trim())
      .filter(text => text && text.length > 0 && text.length < 40);

    if (chips.length > 3) {
      context.push(`Categorías: ${[...new Set(chips)].join(', ')}`);
    }

    // ========== BÚSQUEDA ACTIVA ==========
    const searchInput = document.querySelector('input[type="text"]') as HTMLInputElement;
    if (searchInput?.value?.trim()) {
      context.push(`Búsqueda: "${searchInput.value}"`);
    }

    // ========== DETECTAR Y CAPTURAR CONTENIDO ESPECÍFICO POR TIPO ==========

    // 1. LISTAS (página /lists o cards de listas)
    const listCards = Array.from(document.querySelectorAll('a[href^="/lists/"]'));
    if (listCards.length > 0) {
      context.push(`\n\n========== LISTAS (${listCards.length}) ==========`);
      listCards.forEach((card, idx) => {
        const title = card.querySelector('h3')?.textContent?.trim() || 'Sin título';
        const badges = Array.from(card.querySelectorAll('span[class*="font-bold"]'))
          .map(b => b.textContent?.trim()).filter(Boolean);
        const category = card.querySelector('span[class*="text-[#51a2ff]"]')?.textContent?.trim();
        const author = card.textContent?.match(/por\s+(.+?)(?=\d|\s*$)/)?.[1]?.trim();
        const description = card.querySelector('p[class*="line-clamp"]')?.textContent?.trim();
        const likes = card.textContent?.match(/(\d+)/)?.[1];
        const games = card.textContent?.match(/(\d+)\s*juegos?/i)?.[1];

        context.push(`\n${idx + 1}. ${title}`);
        if (badges.length > 0) context.push(`   Badges: ${badges.join(', ')}`);
        if (category) context.push(`   Categoría: ${category}`);
        if (author) context.push(`   Autor: ${author}`);
        if (description) context.push(`   Descripción: ${description}`);
        if (likes || games) context.push(`   Stats: ${likes ? `${likes} likes` : ''} ${games ? `${games} juegos` : ''}`.trim());
      });
      context.push(`========== FIN LISTAS ==========\n`);
    }

    // 2. DETALLE DE LISTA (página /lists/:id)
    if (path.includes('/lists/') && !path.endsWith('/lists')) {
      const listTitle = document.querySelector('h1, h2')?.textContent?.trim();
      const listDesc = document.querySelector('p[class*="text-"]')?.textContent?.trim();
      const gameItems = Array.from(document.querySelectorAll('[class*="game"], li, [class*="item"]'))
        .map(el => el.textContent?.trim())
        .filter(text => text && text.length > 5 && text.length < 200);

      if (listTitle) {
        context.push(`\n\n========== DETALLE DE LISTA ==========`);
        context.push(`Título: ${listTitle}`);
        if (listDesc) context.push(`Descripción: ${listDesc}`);
        if (gameItems.length > 0) {
          context.push(`\nJuegos en la lista (${gameItems.length}):`);
          gameItems.forEach((game, idx) => context.push(`${idx + 1}. ${game}`));
        }
        context.push(`========== FIN DETALLE ==========\n`);
      }
    }

    // 3. AMIGOS (página /friends)
    if (path.includes('/friends')) {
      const friendElements = Array.from(document.querySelectorAll('[class*="friend"], [class*="player"], [class*="user"]'));
      if (friendElements.length > 0) {
        context.push(`\n\n========== AMIGOS (${friendElements.length}) ==========`);
        friendElements.slice(0, 50).forEach((friend, idx) => {
          const name = friend.querySelector('[class*="name"], h3, h4')?.textContent?.trim();
          const status = friend.querySelector('[class*="status"], [class*="online"]')?.textContent?.trim();
          const game = friend.querySelector('[class*="game"]')?.textContent?.trim();

          if (name) {
            let line = `${idx + 1}. ${name}`;
            if (status) line += ` - ${status}`;
            if (game) line += ` (jugando: ${game})`;
            context.push(line);
          }
        });
        context.push(`========== FIN AMIGOS ==========\n`);
      }
    }

    // 4. PERFIL (página /profile)
    if (path.includes('/profile')) {
      const userName = document.querySelector('[class*="persona"], h1, h2')?.textContent?.trim();
      const stats = Array.from(document.querySelectorAll('[class*="stat"], [class*="metric"], [class*="count"]'))
        .map(el => el.textContent?.trim())
        .filter(text => text && text.length < 100);

      if (userName || stats.length > 0) {
        context.push(`\n\n========== PERFIL ==========`);
        if (userName) context.push(`Usuario: ${userName}`);
        if (stats.length > 0) {
          context.push(`\nEstadísticas:`);
          stats.forEach(stat => context.push(`- ${stat}`));
        }
        context.push(`========== FIN PERFIL ==========\n`);
      }
    }

    // 5. JUEGOS (grid de juegos en cualquier página)
    const gameCards = Array.from(document.querySelectorAll('[href^="/game/"], [class*="game-card"], [class*="game-item"]'));
    if (gameCards.length > 0 && listCards.length === 0) {
      context.push(`\n\n========== JUEGOS (${gameCards.length}) ==========`);
      gameCards.slice(0, 30).forEach((card, idx) => {
        const name = card.querySelector('h2, h3, h4, [alt]')?.textContent?.trim() ||
                     card.querySelector('img')?.getAttribute('alt');
        const price = card.querySelector('[class*="price"]')?.textContent?.trim();
        const discount = card.querySelector('[class*="discount"], [class*="sale"]')?.textContent?.trim();
        const tags = Array.from(card.querySelectorAll('[class*="tag"], [class*="genre"]'))
          .map(t => t.textContent?.trim()).filter(Boolean);

        if (name) {
          let line = `${idx + 1}. ${name}`;
          if (discount) line += ` ${discount}`;
          if (price) line += ` - ${price}`;
          if (tags.length > 0) line += ` [${tags.join(', ')}]`;
          context.push(line);
        }
      });
      context.push(`========== FIN JUEGOS ==========\n`);
    }

    // 6. MERCADO/OFERTAS (página /market)
    if (path.includes('/market')) {
      const offerCards = Array.from(document.querySelectorAll('[class*="offer"], [class*="deal"], [class*="sale"]'));
      if (offerCards.length > 0) {
        context.push(`\n\n========== OFERTAS (${offerCards.length}) ==========`);
        offerCards.slice(0, 20).forEach((card, idx) => {
          const offer = card.textContent?.trim();
          if (offer && offer.length < 200) {
            context.push(`${idx + 1}. ${offer}`);
          }
        });
        context.push(`========== FIN OFERTAS ==========\n`);
      }
    }

    // 7. HOME (página principal)
    if (path === '/' || path === '/home') {
      const sections = Array.from(document.querySelectorAll('section, [class*="section"], [class*="carousel"]'));
      if (sections.length > 0) {
        context.push(`\n\n========== HOME - SECCIONES ==========`);
        sections.slice(0, 10).forEach((section, idx) => {
          const heading = section.querySelector('h1, h2, h3')?.textContent?.trim();
          const items = Array.from(section.querySelectorAll('[class*="card"], [class*="item"]'))
            .map(item => item.textContent?.trim().slice(0, 100))
            .filter(Boolean)
            .slice(0, 5);

          if (heading) {
            context.push(`\n${idx + 1}. ${heading}`);
            if (items.length > 0) {
              items.forEach(item => context.push(`   - ${item}`));
            }
          }
        });
        context.push(`========== FIN HOME ==========\n`);
      }
    }

    // 8. TABLA/LEADERBOARD (admin, stats, etc.)
    const tables = Array.from(document.querySelectorAll('table, [role="table"]'));
    if (tables.length > 0) {
      context.push(`\n\n========== TABLAS/DATOS ==========`);
      tables.forEach((table, idx) => {
        const headers = Array.from(table.querySelectorAll('th'))
          .map(th => th.textContent?.trim()).filter(Boolean);
        const rows = Array.from(table.querySelectorAll('tbody tr')).slice(0, 20);

        if (headers.length > 0) {
          context.push(`\nTabla ${idx + 1}: ${headers.join(' | ')}`);
          rows.forEach((row, rowIdx) => {
            const cells = Array.from(row.querySelectorAll('td'))
              .map(td => td.textContent?.trim()).filter(Boolean);
            if (cells.length > 0) {
              context.push(`${rowIdx + 1}. ${cells.join(' | ')}`);
            }
          });
        }
      });
      context.push(`========== FIN TABLAS ==========\n`);
    }

    // 9. BOTONES/ACCIONES IMPORTANTES
    const actionButtons = Array.from(
      document.querySelectorAll('button[class*="bg-[#009966]"], button[class*="bg-[#155dfc]"], [class*="btn-primary"]')
    )
      .map(btn => btn.textContent?.trim())
      .filter(text => text && text.length < 50);

    if (actionButtons.length > 0) {
      context.push(`\nAcciones: ${[...new Set(actionButtons)].join(', ')}`);
    }

    // 10. CONTENIDO GENÉRICO (fallback si nada específico fue capturado)
    if (context.length < 8) {
      const mainContent = document.querySelector('main, [role="main"], #root > div > div');
      if (mainContent?.textContent?.trim()) {
        const allText = mainContent.textContent.trim();
        context.push(`\n\n========== TODO EL CONTENIDO ==========\n${allText}\n========== FIN ==========`);
      }
    }

    return context.join('\n');
  };

  const handleToggleScreenContext = () => {
    setHasScreenContext(!hasScreenContext);
  };

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userText = input.trim();
    const screenContext = hasScreenContext ? captureScreenContext() : null;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: userText,
      hasScreenContext: !!screenContext,
      image: attachedImage || undefined
    };
    setMessages(prev => [...prev, userMsg]);
    setInput("");
    setLoading(true);

    try {
      const response = await api.post('/api/chat/message', {
        message: userText,
        sessionId,
        userId: user?.steamid || 'anonymous',
        steamId: user?.steamid || null,
        screenContext: screenContext || undefined,
        includeSteamContext: true,
        image: attachedImage || undefined
      });

      // Clear image after sending
      if (attachedImage) {
        setAttachedImage(null);
        if (fileInputRef.current) {
          fileInputRef.current.value = '';
        }
      }

      const data = response.data;
      if (data.sessionId) {
        setSessionId(data.sessionId);
      }

      const aiMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        text: data.response || 'Lo siento, no pude generar una respuesta.',
      };
      setMessages(prev => [...prev, aiMsg]);
    } catch (error) {
      console.error("AI Error:", error);
      const errorMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        text: "Lo siento, tuve un problema al procesar tu solicitud. Intenta de nuevo más tarde."
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setLoading(false);
    }
  };

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setAttachedImage(e.target?.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  // Capture screen/window/tab
  const handleCaptureScreen = async () => {
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({
        video: { mediaSource: 'screen' } as any
      });

      // Create video element to capture frame
      const video = document.createElement('video');
      video.srcObject = stream;
      video.play();

      // Wait for video to be ready
      await new Promise<void>((resolve) => {
        video.onloadedmetadata = () => resolve();
      });

      // Capture frame to canvas
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(video, 0, 0);

      // Stop all tracks
      stream.getTracks().forEach(track => track.stop());

      // Convert to base64
      const dataUrl = canvas.toDataURL('image/png');
      setAttachedImage(dataUrl);
    } catch (error) {
      console.error('Screen capture error:', error);
      // User probably cancelled the permission dialog
    }
  };

  const [isDragging, setIsDragging] = useState(false);

  const processImageFile = (file: File) => {
    // Check if it's an image
    if (!file.type.startsWith('image/')) {
      alert('Por favor selecciona una imagen válida');
      return;
    }

    // Check file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
      alert('La imagen es muy grande. Máximo 5MB');
      return;
    }

    // Convert to base64
    const reader = new FileReader();
    reader.onloadend = () => {
      setAttachedImage(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImageFile(file);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) {
      processImageFile(file);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const items = e.clipboardData?.items;
    if (!items) return;

    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1) {
        const file = items[i].getAsFile();
        if (file) {
          processImageFile(file);
        }
        break;
      }
    }
  };

  const handleAttachImage = () => {
    fileInputRef.current?.click();
  };

  const handleRemoveImage = () => {
    setAttachedImage(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  return (
    <>
      <button
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 right-6 md:bottom-10 md:right-10 z-40 bg-gradient-to-r from-blue-600 to-cyan-500 hover:from-blue-500 hover:to-cyan-400 text-white p-4 rounded-full shadow-lg shadow-blue-500/30 transition-all hover:scale-110 group"
      >
        <Bot size={28} className="group-hover:animate-bounce" />
        <span className="absolute -top-2 -right-2 w-4 h-4 bg-red-500 rounded-full animate-pulse border-2 border-slate-900"></span>
      </button>

      <AnimatePresence>
        {isOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsOpen(false)}
              className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm z-50"
            />
            <motion.div
              initial={{ opacity: 0, y: 100, scale: 0.9 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 100, scale: 0.9 }}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              className={`fixed z-50 bg-slate-900 border ${isDragging ? 'border-blue-500 shadow-[0_0_20px_rgba(59,130,246,0.5)]' : 'border-slate-700'} rounded-2xl shadow-2xl flex flex-col overflow-hidden transition-all ${
                isExpanded
                  ? 'inset-4 md:inset-8 lg:inset-16' // Modo expandido (pantalla completa con margen)
                  : 'bottom-20 right-4 md:bottom-28 md:right-10 w-[calc(100vw-2rem)] sm:w-[400px] lg:w-[450px] h-[70vh] sm:h-[500px] md:h-[600px]' // Modo normal (responsive)
              }`}
            >
              {/* Header */}
              <div className="bg-gradient-to-r from-slate-800 to-slate-900 p-4 border-b border-slate-700 flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-blue-500/20 rounded-full flex items-center justify-center text-blue-400">
                    <Sparkles size={20} />
                  </div>
                  <div>
                    <h3 className="font-bold text-white">SteaMate AI</h3>
                    <p className="text-xs text-green-400 flex items-center gap-1">
                      <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span> Online
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => setIsExpanded(!isExpanded)}
                    className="text-slate-400 hover:text-white transition-colors p-1"
                    title={isExpanded ? "Minimizar ventana" : "Agrandar ventana"}
                  >
                    {isExpanded ? <Minimize2 size={20} /> : <Maximize2 size={20} />}
                  </button>
                  <button
                    onClick={() => setIsOpen(false)}
                    className="text-slate-400 hover:text-white transition-colors"
                  >
                    <X size={20} />
                  </button>
                </div>
              </div>

              {/* Chat Area */}
              <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-950/50">
                {messages.map((msg, idx) => (
                  <div
                    key={msg.id || idx}
                    className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div
                      className={`max-w-[85%] flex flex-col p-3 rounded-2xl text-sm leading-relaxed ${msg.role === 'user'
                          ? 'bg-blue-600 text-white rounded-br-none shadow-md shadow-blue-900/20'
                          : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700 shadow-sm'
                        }`}
                    >
                      {msg.role === 'assistant' && (
                        <div className="flex items-center gap-2 mb-1 text-[10px] text-blue-400 font-bold uppercase tracking-wider">
                          <Bot size={12} /> SteaMate AI
                        </div>
                      )}
                      
                      {msg.image && (
                        <div className="mb-2 rounded-lg overflow-hidden border border-white/10">
                          <img src={msg.image} alt="Usuario" className="max-w-full h-auto max-h-48 object-cover" />
                        </div>
                      )}

                      {msg.hasScreenContext && (
                        <div className="flex items-center gap-2 mb-2 text-xs text-cyan-200 bg-cyan-900/40 p-1.5 rounded inline-flex w-fit">
                          <Eye size={12} /> Contexto de pantalla
                        </div>
                      )}
                      
                      <p className="whitespace-pre-wrap">{msg.text}</p>
                    </div>
                  </div>
                ))}
                {loading && (
                  <div className="flex justify-start">
                    <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700">
                      <div className="flex gap-1">
                        <span className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-0"></span>
                        <span className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-150"></span>
                        <span className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-300"></span>
                      </div>
                    </div>
                  </div>
                )}
                <div ref={messagesEndRef} />
              </div>

              {/* Input Area */}
              <div className="p-4 bg-slate-900 border-t border-slate-700 flex flex-col gap-2">
                
                {/* Image Preview */}
                {attachedImage && (
                  <div className="relative inline-block w-fit mb-2">
                    <div className="border-2 border-blue-500/50 rounded-lg overflow-hidden p-1 bg-slate-950">
                      <img src={attachedImage} alt="Adjunto" className="h-20 w-auto object-cover rounded" />
                      <button 
                        onClick={handleRemoveImage}
                        className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md hover:bg-red-400 transition-colors"
                      >
                        <XCircle size={16} />
                      </button>
                    </div>
                  </div>
                )}

                <div className="flex items-center gap-2">
                  <input 
                    type="file" 
                    accept="image/*" 
                    className="hidden" 
                    ref={fileInputRef}
                    onChange={handleFileChange}
                  />

                  <button
                    onClick={handleAttachImage}
                    disabled={loading}
                    className="text-slate-400 hover:text-blue-400 p-2 rounded-lg hover:bg-slate-800 transition-colors"
                    title="Subir imagen"
                  >
                    <ImageIcon size={20} />
                  </button>

                  {/* Screen context toggle button */}
                  <button
                    onClick={handleToggleScreenContext}
                    disabled={loading}
                    className={`transition-all disabled:opacity-50 disabled:cursor-not-allowed p-2 rounded-lg ${
                      hasScreenContext
                        ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/50'
                        : 'text-slate-400 hover:text-cyan-400 hover:bg-slate-800'
                    }`}
                    title={hasScreenContext ? "Contexto de pantalla activado" : "Dar contexto de pantalla"}
                  >
                    <Eye size={20} />
                  </button>

                  {/* Input field */}
                  <div className="flex-1 flex items-center justify-between bg-slate-950 border border-slate-700 rounded-xl px-4 py-2 focus-within:border-blue-500 transition-colors">
                    <input
                      type="text"
                      value={input}
                      onChange={(e) => setInput(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                      onPaste={handlePaste}
                      placeholder={hasScreenContext ? "Pregunta sobre lo que ves..." : "Escribe o pega una imagen..."}
                      className="flex-1 bg-transparent text-white placeholder-slate-500 focus:outline-none"
                    />
                    <button
                      onClick={handleSend}
                      disabled={loading}
                      className="text-blue-500 hover:text-blue-400 transition-colors disabled:opacity-50"
                    >
                      <Send size={20} />
                    </button>
                  </div>
                </div>
                {hasScreenContext && (
                  <div className="mt-2 text-xs flex items-center gap-3">
                    <span className="text-cyan-400 flex items-center gap-1">
                      <Eye size={12} />
                      Contexto de pantalla
                    </span>
                  </div>
                )}
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </>
  );
}

import {
  Tooltip, ResponsiveContainer,
  Cell, RadialBarChart, RadialBar, Legend
} from 'recharts';
import { Trophy, Star, Medal, Crown, Gem, Shield, Sparkles } from 'lucide-react';

const tooltipStyle = {
  backgroundColor: '#0f172a',
  borderColor: '#1e293b',
  color: '#f8fafc',
  borderRadius: '12px',
  border: '1px solid #334155',
  boxShadow: '0 25px 50px -12px rgba(0,0,0,0.5)',
};

interface RarestAchievement {
  name: string;
  game: string;
  globalPercent: number; // % of Steam players who have it
}

interface PlayerAchievements {
  name: string;
  color: string;
  completionRate: number;    // avg % achievements unlocked
  perfectGames: number;      // games at 100%
  totalGamesPlayed: number;
  totalAchievements: number;
  rarestAchievement: RarestAchievement;
}

interface Props {
  players: PlayerAchievements[];
}

export function AchievementCharts({ players }: Props) {
  const completionData = [...players]
    .sort((a, b) => b.completionRate - a.completionRate)
    .map(p => ({ ...p, fill: p.color }));

  const perfectData = [...players]
    .sort((a, b) => b.perfectGames - a.perfectGames);

  const rarestData = [...players]
    .sort((a, b) => a.rarestAchievement.globalPercent - b.rarestAchievement.globalPercent);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Section Header */}
      <div className="bg-gradient-to-r from-amber-900/30 via-yellow-900/20 to-orange-900/30 border border-amber-500/20 rounded-3xl p-6 flex items-center gap-4">
        <div className="bg-amber-500/20 p-3 rounded-2xl">
          <Trophy className="text-amber-400 w-7 h-7" />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-white">El Sudor y los Logros</h2>
          <p className="text-slate-400 text-sm mt-1">El "Tryhardismo" — tener muchos juegos no significa ser bueno, ni terminarlos</p>
        </div>
      </div>

      {/* Row 1: Completion Rate + Perfect Games */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        {/* 1. TASA MEDIA DE FINALIZACIÓN */}
        <div className="bg-slate-900/80 backdrop-blur border border-slate-800 rounded-3xl p-6 shadow-xl">
          <div className="flex justify-between items-start mb-1">
            <div>
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <Medal className="text-amber-400" size={20} /> Tasa de Finalización
              </h3>
              <p className="text-xs text-slate-500 mt-1">% medio de logros desbloqueados por juego empezado</p>
            </div>
            <div className="flex items-center gap-1.5 bg-amber-500/10 border border-amber-500/20 rounded-full px-3 py-1">
              <Crown size={12} className="text-amber-400" />
              <span className="text-[10px] font-bold text-amber-400">{completionData[0]?.name}</span>
            </div>
          </div>

          <div className="h-[320px] w-full mt-4">
            <ResponsiveContainer width="100%" height="100%">
              <RadialBarChart cx="50%" cy="50%" innerRadius="20%" outerRadius="95%" barSize={18} data={completionData}>
                <RadialBar
                  label={{ position: 'insideStart', fill: '#fff', fontSize: 10, fontWeight: 'bold' }}
                  background={{ fill: '#1e293b' }}
                  dataKey="completionRate"
                  cornerRadius={10}
                >
                  {completionData.map((entry, index) => (
                    <Cell key={index} fill={entry.color} />
                  ))}
                </RadialBar>
                <Legend
                  iconSize={8}
                  layout="vertical"
                  verticalAlign="middle"
                  wrapperStyle={{ right: -10, fontSize: '11px' }}
                  formatter={(value, entry: any) => {
                    const player = completionData.find(p => p.name === value);
                    return `${value} (${player?.completionRate}%)`;
                  }}
                />
                <Tooltip contentStyle={tooltipStyle} formatter={(v: number) => [`${v}%`, 'Completado']} />
              </RadialBarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* 2. EL SALÓN DE LA FAMA - JUEGOS PERFECTOS */}
        <div className="bg-slate-900/80 backdrop-blur border border-slate-800 rounded-3xl p-6 shadow-xl">
          <h3 className="text-lg font-bold text-white flex items-center gap-2 mb-1">
            <Sparkles className="text-yellow-400" size={20} /> Salón de la Fama
          </h3>
          <p className="text-xs text-slate-500 mb-5">Juegos completados al 100% de logros</p>

          <div className="space-y-4">
            {perfectData.map((player, i) => (
              <div key={player.name} className="group relative">
                <div className="bg-slate-800/40 rounded-2xl p-4 border border-slate-700/30 hover:border-amber-500/30 transition-all">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg font-black ${
                        i === 0 ? 'bg-gradient-to-br from-amber-500 to-yellow-600 text-black shadow-lg shadow-amber-500/20' :
                        i === 1 ? 'bg-gradient-to-br from-slate-300 to-slate-400 text-black' :
                        i === 2 ? 'bg-gradient-to-br from-amber-700 to-amber-800 text-white' :
                        'bg-slate-700 text-slate-400'
                      }`}>
                        {i === 0 ? '👑' : i + 1}
                      </div>
                      <div>
                        <span className="text-sm font-bold text-white">{player.name}</span>
                        <div className="flex items-center gap-2 mt-0.5">
                          <span className="text-[10px] text-slate-500">{player.totalAchievements} logros totales</span>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="flex items-center gap-1">
                        <Star size={14} className="text-amber-400" />
                        <span className="text-2xl font-black" style={{ color: player.color }}>{player.perfectGames}</span>
                      </div>
                      <span className="text-[10px] text-slate-500">perfectos de {player.totalGamesPlayed}</span>
                    </div>
                  </div>
                  {/* Perfect rate bar */}
                  <div className="mt-3">
                    <div className="h-1.5 bg-slate-700 rounded-full overflow-hidden">
                      <div
                        className="h-full rounded-full"
                        style={{
                          width: `${(player.perfectGames / player.totalGamesPlayed) * 100}%`,
                          background: `linear-gradient(90deg, ${player.color}, #fbbf24)`,
                        }}
                      />
                    </div>
                    <span className="text-[9px] text-slate-600 mt-0.5 block text-right">
                      {((player.perfectGames / player.totalGamesPlayed) * 100).toFixed(1)}% perfeccionados
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Row 2: Rarest Achievement */}
      <div className="bg-slate-900/80 backdrop-blur border border-slate-800 rounded-3xl p-6 shadow-xl">
        <h3 className="text-lg font-bold text-white flex items-center gap-2 mb-1">
          <Gem className="text-purple-400" size={20} /> El Cazatrofeos — Rareza Máxima
        </h3>
        <p className="text-xs text-slate-500 mb-6">El logro más raro que ha conseguido cada miembro del grupo</p>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {rarestData.map((player, i) => {
            const rarityLevel = player.rarestAchievement.globalPercent < 0.5
              ? { label: 'ULTRA RARO', color: 'text-red-400', bg: 'bg-red-500/10', border: 'border-red-500/20', glow: 'shadow-red-500/10' }
              : player.rarestAchievement.globalPercent < 2
              ? { label: 'MUY RARO', color: 'text-purple-400', bg: 'bg-purple-500/10', border: 'border-purple-500/20', glow: 'shadow-purple-500/10' }
              : player.rarestAchievement.globalPercent < 5
              ? { label: 'RARO', color: 'text-blue-400', bg: 'bg-blue-500/10', border: 'border-blue-500/20', glow: 'shadow-blue-500/10' }
              : { label: 'UNCOMMON', color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20', glow: 'shadow-emerald-500/10' };

            return (
              <div
                key={player.name}
                className={`relative bg-slate-800/50 rounded-2xl p-5 border ${rarityLevel.border} hover:shadow-xl ${rarityLevel.glow} transition-all group overflow-hidden`}
              >
                {/* Rarity glow effect */}
                {player.rarestAchievement.globalPercent < 1 && (
                  <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-bl from-amber-500/10 to-transparent rounded-bl-full pointer-events-none" />
                )}

                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <div className="w-8 h-8 rounded-full flex items-center justify-center text-xs font-black" style={{ backgroundColor: player.color + '20', color: player.color }}>
                      {player.name.charAt(0)}
                    </div>
                    <span className="text-sm font-bold text-white">{player.name}</span>
                  </div>
                  <span className={`text-[9px] font-black tracking-wider px-2 py-0.5 rounded-full ${rarityLevel.bg} ${rarityLevel.color} ${rarityLevel.border} border`}>
                    {rarityLevel.label}
                  </span>
                </div>

                <div className="mb-3">
                  <div className="flex items-center gap-2 mb-1">
                    <Shield size={14} className={rarityLevel.color} />
                    <span className="text-sm font-semibold text-white">{player.rarestAchievement.name}</span>
                  </div>
                  <span className="text-[10px] text-slate-500 block">{player.rarestAchievement.game}</span>
                </div>

                {/* Rarity bar */}
                <div className="bg-slate-700/50 rounded-full h-2 overflow-hidden">
                  <div
                    className="h-full rounded-full transition-all duration-1000"
                    style={{
                      width: `${Math.max(player.rarestAchievement.globalPercent, 0.5)}%`,
                      background: player.color,
                    }}
                  />
                </div>
                <div className="flex justify-between mt-1">
                  <span className={`text-xs font-black ${rarityLevel.color}`}>
                    {player.rarestAchievement.globalPercent}%
                  </span>
                  <span className="text-[9px] text-slate-600">de jugadores globales</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { useState } from 'react';

interface GenreTime {
  name: string;
  value: number;
}

interface Props {
  userA?: { name: string; data: GenreTime[] };
  userB?: { name: string; data: GenreTime[] };
}

const GENRE_COLORS: Record<string, string> = {
  RPG: '#8b5cf6',
  FPS: '#ef4444',
  Estrategia: '#3b82f6',
  Indie: '#10b981',
  Simulación: '#f59e0b',
  Cooperativo: '#ec4899',
  Acción: '#f97316',
  Carreras: '#06b6d4',
  Terror: '#6366f1',
  MOBA: '#84cc16',
};

const DEFAULT_USER_A = {
  name: 'Yo',
  data: [
    { name: 'RPG', value: 420 },
    { name: 'FPS', value: 310 },
    { name: 'Estrategia', value: 180 },
    { name: 'Indie', value: 150 },
    { name: 'Cooperativo', value: 240 },
  ],
};

const DEFAULT_USER_B = {
  name: 'SarahPro',
  data: [
    { name: 'RPG', value: 500 },
    { name: 'Estrategia', value: 380 },
    { name: 'Indie', value: 290 },
    { name: 'Cooperativo', value: 120 },
    { name: 'Simulación', value: 90 },
  ],
};

const getColor = (name: string) => GENRE_COLORS[name] || '#64748b';

const CustomTooltip = ({ active, payload }: any) => {
  if (!active || !payload?.length) return null;
  const d = payload[0];
  return (
    <div className="bg-slate-950 border border-slate-700 rounded-xl p-3 shadow-2xl text-xs">
      <div className="flex items-center gap-2 mb-1">
        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: d.payload.fill || d.color }}></div>
        <span className="text-white font-bold">{d.name}</span>
      </div>
      <p className="text-slate-300">{d.value} horas jugadas</p>
    </div>
  );
};

export function AffinityDoughnut({ userA = DEFAULT_USER_A, userB = DEFAULT_USER_B }: Props) {
  const [activeRing, setActiveRing] = useState<'inner' | 'outer' | null>(null);

  return (
    <div className="bg-slate-900/80 backdrop-blur border border-slate-800 rounded-3xl p-6 shadow-xl">
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-lg font-bold text-white flex items-center gap-2">
          <span className="text-2xl">🔗</span> Afinidad de Tiempo de Juego
        </h3>
        <span className="text-[10px] uppercase tracking-wider text-slate-500 bg-slate-800 px-2 py-1 rounded-full">Anillos Concéntricos</span>
      </div>
      <p className="text-xs text-slate-500 mb-5">
        Anillo interior = <span className="text-blue-400">{userA.name}</span> · Anillo exterior = <span className="text-pink-400">{userB.name}</span> — colores alineados por género.
      </p>

      <div className="h-[320px] w-full relative">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            {/* Inner ring - User A */}
            <Pie
              data={userA.data}
              cx="50%"
              cy="50%"
              innerRadius={45}
              outerRadius={80}
              paddingAngle={3}
              dataKey="value"
              nameKey="name"
              onMouseEnter={() => setActiveRing('inner')}
              onMouseLeave={() => setActiveRing(null)}
              animationDuration={1200}
              stroke="transparent"
            >
              {userA.data.map((entry) => (
                <Cell
                  key={entry.name}
                  fill={getColor(entry.name)}
                  fillOpacity={activeRing === 'outer' ? 0.3 : 0.9}
                  className="transition-opacity duration-300"
                />
              ))}
            </Pie>

            {/* Outer ring - User B */}
            <Pie
              data={userB.data}
              cx="50%"
              cy="50%"
              innerRadius={90}
              outerRadius={125}
              paddingAngle={3}
              dataKey="value"
              nameKey="name"
              onMouseEnter={() => setActiveRing('outer')}
              onMouseLeave={() => setActiveRing(null)}
              animationDuration={1500}
              stroke="transparent"
            >
              {userB.data.map((entry) => (
                <Cell
                  key={entry.name}
                  fill={getColor(entry.name)}
                  fillOpacity={activeRing === 'inner' ? 0.3 : 0.9}
                  className="transition-opacity duration-300"
                />
              ))}
            </Pie>

            <Tooltip content={<CustomTooltip />} />
            <Legend
              verticalAlign="bottom"
              iconType="circle"
              iconSize={8}
              wrapperStyle={{ fontSize: 10, paddingTop: 12 }}
            />
          </PieChart>
        </ResponsiveContainer>

        {/* Center label */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="text-center">
            <p className="text-xl font-bold text-white">
              {activeRing === 'inner' ? userA.name : activeRing === 'outer' ? userB.name : 'VS'}
            </p>
            <p className="text-[10px] text-slate-500 uppercase tracking-wider">
              {activeRing ? 'Tiempo por género' : 'Comparativa'}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

