              <Bar dataKey="votos" name="Votos" fill="#8b5cf6" radius={[4, 4, 0, 0]} barSize={14} fillOpacity={0.85} />
              <Bar dataKey="comments" name="Comentarios" fill="#10b981" radius={[4, 4, 0, 0]} barSize={14} fillOpacity={0.85} />
