      <div className="mt-2 pt-2 border-t border-slate-800">
        <p className="text-slate-400">Tasa de conversión: <span className="text-white font-bold">{rate}%</span></p>
      </div>
    </div>
  );
};

export function TractionChart({ data = DEFAULT_DATA, listName = 'Top RPGs de 2024' }: Props) {
  const totalViews = data.reduce((sum, d) => sum + d.views, 0);
  const totalInteractions = data.reduce((sum, d) => sum + d.interactions, 0);
  const conversionRate = totalViews > 0 ? Math.round((totalInteractions / totalViews) * 100) : 0;

  return (
    <div className="bg-slate-900/80 backdrop-blur border border-slate-800 rounded-3xl p-6 shadow-xl">
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-lg font-bold text-white flex items-center gap-2">
          <span className="text-2xl">📈</span> Tracción de la Publicación
        </h3>
        <span className="text-[10px] uppercase tracking-wider text-slate-500 bg-slate-800 px-2 py-1 rounded-full">Área Chart</span>
      </div>
      <p className="text-xs text-slate-500 mb-4">
        Rendimiento de "<span className="text-cyan-400">{listName}</span>" en los últimos 7 días.
      </p>

      {/* Stats row */}
      <div className="grid grid-cols-3 gap-3 mb-5">
        <div className="bg-slate-800/50 rounded-xl p-3 text-center border border-slate-700/50">
          <p className="text-lg font-bold text-white">{totalViews.toLocaleString()}</p>
          <p className="text-[10px] text-slate-500 uppercase tracking-wider">Views</p>
        </div>
        <div className="bg-slate-800/50 rounded-xl p-3 text-center border border-slate-700/50">
          <p className="text-lg font-bold text-white">{totalInteractions.toLocaleString()}</p>
          <p className="text-[10px] text-slate-500 uppercase tracking-wider">Interacciones</p>
        </div>
        <div className="bg-slate-800/50 rounded-xl p-3 text-center border border-slate-700/50">
          <p className="text-lg font-bold text-white">{conversionRate}%</p>
          <p className="text-[10px] text-slate-500 uppercase tracking-wider">Conversión</p>
        </div>
      </div>

      <div className="h-[260px] w-full">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data} margin={{ top: 5, right: 10, left: 0, bottom: 0 }}>
            <defs>
              <linearGradient id="tractionViews" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#06b6d4" stopOpacity={0.6} />
                <stop offset="95%" stopColor="#06b6d4" stopOpacity={0} />
              </linearGradient>
              <linearGradient id="tractionInteractions" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#a855f7" stopOpacity={0.6} />
                <stop offset="95%" stopColor="#a855f7" stopOpacity={0} />
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
            <XAxis dataKey="day" stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
            <YAxis stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
            <Tooltip content={<CustomTooltip />} />
            <Legend verticalAlign="top" height={30} iconType="circle" iconSize={8} wrapperStyle={{ fontSize: 11 }} />
            <Area
              type="monotone"
              dataKey="views"
              name="Visualizaciones"
              stroke="#06b6d4"
              strokeWidth={2.5}
              fillOpacity={1}
              fill="url(#tractionViews)"
              animationDuration={1200}
            />
            <Area
              type="monotone"
              dataKey="interactions"
              name="Guardados/Interacciones"
              stroke="#a855f7"
              strokeWidth={2.5}
              fillOpacity={1}
              fill="url(#tractionInteractions)"
              animationDuration={1500}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import {
  RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar,
  ResponsiveContainer, Tooltip, Legend
} from 'recharts';
import { Hexagon, Info } from 'lucide-react';
import { useState } from 'react';

const tooltipStyle = {
  backgroundColor: '#0f172a',
  borderColor: '#1e293b',
  color: '#f8fafc',
  borderRadius: '12px',
  border: '1px solid #334155',
  boxShadow: '0 25px 50px -12px rgba(0,0,0,0.5)',
};

interface PlayerRadar {
  name: string;
  color: string;
  avatar: string;
  // Raw values for archetype calculation
  rawVolume: number;
  rawDedication: number;
  rawProfitability: number; // inverted: lower cost = higher score
  rawPerfectionism: number;
  rawLoyalty: number;
  // Scores 1-10 (normalized within group)
  volume: number;       // Library size
  dedication: number;   // Total hours
  profitability: number; // Cost per hour (inverted)
  perfectionism: number; // Achievement completion rate
  loyalty: number;       // % hours in top game
}

interface Props {
  players: PlayerRadar[];
}

const AXIS_LABELS: Record<string, { label: string; description: string; icon: string }> = {
  'Volumen': { label: 'Volumen', description: 'Tamaño de la biblioteca', icon: '📚' },
  'Dedicación': { label: 'Dedicación', description: 'Horas totales jugadas', icon: '⏰' },
  'Rentabilidad': { label: 'Rentabilidad', description: 'Menor coste por hora', icon: '💰' },
  'Perfeccionismo': { label: 'Perfeccionismo', description: 'Tasa de logros completados', icon: '🏆' },
  'Fidelidad': { label: 'Fidelidad', description: 'Horas concentradas en su top 1', icon: '❤️' },
};

function getArchetype(player: PlayerRadar): { name: string; emoji: string; description: string } {
  const scores = {
    volume: player.volume,
    dedication: player.dedication,
    profitability: player.profitability,
    perfectionism: player.perfectionism,
    loyalty: player.loyalty,
  };
  
  const max = Object.entries(scores).reduce((a, b) => a[1] > b[1] ? a : b);
  
  switch (max[0]) {
    case 'volume':
      return { name: 'El Coleccionista', emoji: '📚', description: 'Compra más de lo que juega' };
    case 'dedication':
      return { name: 'El No-Life', emoji: '🎮', description: 'Vive dentro de Steam' };
    case 'profitability':
      return { name: 'El Ahorrador', emoji: '💰', description: 'Exprime cada céntimo' };
    case 'perfectionism':
      return { name: 'El Tryhard', emoji: '🏆', description: 'No deja logro sin desbloquear' };
    case 'loyalty':
      return { name: 'El Monotemático', emoji: '❤️', description: 'Tiene su juego favorito y lo demás sobra' };
    default:
      return { name: 'El Equilibrado', emoji: '⚖️', description: 'Un poco de todo' };
  }
}

export function UltimateRadar({ players }: Props) {
  const [highlightedPlayer, setHighlightedPlayer] = useState<string | null>(null);

  // Build radar data
  const radarData = [
    { axis: 'Volumen', ...Object.fromEntries(players.map(p => [p.name, p.volume])) },
    { axis: 'Dedicación', ...Object.fromEntries(players.map(p => [p.name, p.dedication])) },
    { axis: 'Rentabilidad', ...Object.fromEntries(players.map(p => [p.name, p.profitability])) },
    { axis: 'Perfeccionismo', ...Object.fromEntries(players.map(p => [p.name, p.perfectionism])) },
    { axis: 'Fidelidad', ...Object.fromEntries(players.map(p => [p.name, p.loyalty])) },
  ];

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Section Header */}
      <div className="bg-gradient-to-r from-violet-900/30 via-fuchsia-900/20 to-pink-900/30 border border-violet-500/20 rounded-3xl p-6 flex items-center gap-4">
        <div className="bg-violet-500/20 p-3 rounded-2xl">
          <Hexagon className="text-violet-400 w-7 h-7" />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-white">Radar Definitivo</h2>
          <p className="text-slate-400 text-sm mt-1">El perfil completo de cada jugador de un solo vistazo — 5 ejes, puntuados del 1 al 10</p>
        </div>
      </div>

      {/* Main Radar Chart */}
      <div className="bg-slate-900/80 backdrop-blur border border-slate-800 rounded-3xl p-6 shadow-xl">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
            <Hexagon className="text-violet-400" size={20} /> Gráfico de Araña Comparativo
          </h3>
          <div className="flex items-center gap-1 text-[10px] text-slate-500 bg-slate-800 px-2.5 py-1 rounded-lg">
            <Info size={10} /> Puntuación relativa dentro del grupo (1-10)
          </div>
        </div>

        {/* Axis legend */}
        <div className="flex flex-wrap gap-3 mb-4">
          {Object.entries(AXIS_LABELS).map(([key, val]) => (
            <div key={key} className="flex items-center gap-1.5 text-[10px] text-slate-400 bg-slate-800/50 px-2.5 py-1 rounded-lg">
              <span>{val.icon}</span>
              <span className="font-semibold text-slate-300">{val.label}:</span>
              <span>{val.description}</span>
            </div>
          ))}
        </div>

        <div className="h-[420px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <RadarChart cx="50%" cy="50%" outerRadius="75%" data={radarData}>
              <PolarGrid stroke="#334155" strokeDasharray="3 3" />
              <PolarAngleAxis
                dataKey="axis"
                stroke="#94a3b8"
                fontSize={12}
                fontWeight="bold"
                tick={({ x, y, payload }) => {
                  const info = AXIS_LABELS[payload.value];
                  return (
                    <g transform={`translate(${x},${y})`}>
                      <text textAnchor="middle" fill="#94a3b8" fontSize={11} fontWeight="bold" dy={-4}>
                        {info?.icon} {payload.value}
                      </text>
                    </g>
                  );
                }}
              />
              <PolarRadiusAxis
                angle={90}
                domain={[0, 10]}
                stroke="#475569"
                tick={{ fontSize: 9, fill: '#475569' }}
                tickCount={6}
              />
              {players.map(p => (
                <Radar
                  key={p.name}
                  name={p.name}
                  dataKey={p.name}
                  stroke={p.color}
                  fill={p.color}
                  fillOpacity={highlightedPlayer === null ? 0.15 : highlightedPlayer === p.name ? 0.35 : 0.05}
                  strokeOpacity={highlightedPlayer === null ? 1 : highlightedPlayer === p.name ? 1 : 0.2}
                  strokeWidth={highlightedPlayer === p.name ? 3 : 2}
                  animationDuration={1500}
                />
              ))}
              <Tooltip contentStyle={tooltipStyle} />
              <Legend
                wrapperStyle={{ fontSize: '12px', cursor: 'pointer' }}
                onClick={(e: any) => {
                  setHighlightedPlayer(prev => prev === e.value ? null : e.value);
                }}
              />
            </RadarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Archetype Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {players.map((player) => {
          const archetype = getArchetype(player);
          const scores = [
            { axis: 'Volumen', score: player.volume, raw: player.rawVolume.toLocaleString() + ' juegos' },
            { axis: 'Dedicación', score: player.dedication, raw: player.rawDedication.toLocaleString() + 'h' },
            { axis: 'Rentabilidad', score: player.profitability, raw: (1 / (player.rawProfitability || 1)).toFixed(3) + '€/h' },
            { axis: 'Perfeccionismo', score: player.perfectionism, raw: player.rawPerfectionism + '%' },
            { axis: 'Fidelidad', score: player.loyalty, raw: player.rawLoyalty + '%' },
          ];
          const totalScore = scores.reduce((a, b) => a + b.score, 0);
          const avgScore = (totalScore / 5).toFixed(1);

          return (
            <div
              key={player.name}
              className="bg-slate-800/50 rounded-2xl p-5 border border-slate-700/30 hover:border-violet-500/30 transition-all group cursor-default"
              onMouseEnter={() => setHighlightedPlayer(player.name)}
              onMouseLeave={() => setHighlightedPlayer(null)}
            >
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full flex items-center justify-center text-lg" style={{ backgroundColor: player.color + '20' }}>
                    {archetype.emoji}
                  </div>
                  <div>
                    <span className="text-sm font-bold text-white block">{player.name}</span>
                    <span className="text-[10px] font-semibold" style={{ color: player.color }}>{archetype.name}</span>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-lg font-black text-white">{avgScore}</span>
                  <span className="text-[10px] text-slate-500 block">media</span>
                </div>
              </div>

              <p className="text-[10px] text-slate-500 mb-3 italic">"{archetype.description}"</p>

              {/* Score bars */}
              <div className="space-y-2">
                {scores.map(s => (
                  <div key={s.axis} className="flex items-center gap-2">
                    <span className="text-[10px] text-slate-500 w-20 truncate">{AXIS_LABELS[s.axis]?.icon} {s.axis}</span>
                    <div className="flex-1 h-1.5 bg-slate-700 rounded-full overflow-hidden">
                      <div
                        className="h-full rounded-full transition-all duration-700"
                        style={{
                          width: `${(s.score / 10) * 100}%`,
                          backgroundColor: player.color,
                        }}
                      />
                    </div>
                    <span className="text-[10px] font-bold text-white w-4 text-right">{s.score}</span>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { Link, Outlet, useLocation } from "react-router";
import {
  ShoppingBag,
  Bell,
  Users,
  ListOrdered,
  User as UserIcon,
  Menu,
  X,
  Home,
  LogIn,
  LogOut,
  Shield,
  AlertTriangle,
  AlertOctagon,
  MessageSquareOff,
} from "lucide-react";
import { useEffect, useState } from "react";
import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";
import { motion, AnimatePresence } from "motion/react";
import { AssistantModal } from "../ai/AssistantModal";
import { NotificationBell } from "../notifications/NotificationBell";
import { NotificationToasts } from "../notifications/NotificationToasts";
import { useAuth } from "../../context/AuthContext";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "../ui/alert-dialog";

function cn(...inputs: (string | undefined | null | false)[]) {
  return twMerge(clsx(inputs));
}

export function Layout() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [loginNotices, setLoginNotices] = useState<
    { action: "warned" | "silenced"; reason: string }[]
  >([]);
  const [activeNoticeIndex, setActiveNoticeIndex] = useState(0);
  const location = useLocation();
  const { user, logout } = useAuth();
  const isAdmin = user?.role === "admin" || user?.isAdmin === true;
  const warnedNotice = user?.notices?.find((item) => item.action === "warned");
  const silencedNotice = user?.notices?.find(
    (item) => item.action === "silenced",
  );
  const isWarnedUser =
    Boolean(warnedNotice) ||
    user?.status === "warned" ||
    Boolean(user?.warningReason?.trim());
  const isSilencedUser = Boolean(silencedNotice) || user?.status === "silenced";
  const warningTooltip =
    warnedNotice?.reason || user?.warningReason
      ? `Has sido advertido por: \"${warnedNotice?.reason || user?.warningReason || ""}\". Respeta las normas de la comunidad para no ser baneado por un administrador.`
      : "Has sido advertido por incumplir las normas de la comunidad. Respeta las normas de la comunidad para no ser baneado por un administrador.";
  const silencedTooltip = silencedNotice?.reason
    ? `Has sido silenciado por: \"${silencedNotice.reason}\". No puedes publicar ni comentar hasta que un administrador levante la sanción.`
    : "Has sido silenciado por incumplir las normas de la comunidad. No puedes publicar ni comentar hasta que un administrador levante la sanción.";
  const isLoginPage = location.pathname === "/login";
  const activeNotice = loginNotices[activeNoticeIndex] || null;

  useEffect(() => {
    if (!user) {
      setLoginNotices([]);
      setActiveNoticeIndex(0);
      return;
    }

    const pendingNotice = sessionStorage.getItem("steamates_login_notices");
    if (!pendingNotice) {
      return;
    }

    try {
      const parsed = JSON.parse(pendingNotice) as Array<{
        action?: "warned" | "silenced";
        reason?: string;
      }>;
      const notices = parsed
        .filter(
          (item): item is { action: "warned" | "silenced"; reason: string } =>
            item?.action === "warned" || item?.action === "silenced",
        )
        .map((item) => ({
          action: item.action,
          reason: typeof item.reason === "string" ? item.reason : "",
        }));

      setLoginNotices(notices);
      setActiveNoticeIndex(0);
    } catch {
      setLoginNotices([]);
      setActiveNoticeIndex(0);
    }

    sessionStorage.removeItem("steamates_login_notices");
  }, [user]);

  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: "smooth" });
  }, [location.pathname]);

  const closeActiveNotice = () => {
    if (activeNoticeIndex < loginNotices.length - 1) {
      setActiveNoticeIndex((current) => current + 1);
      return;
    }

    setLoginNotices([]);
    setActiveNoticeIndex(0);
  };

  const navItems = [
    { name: "Inicio", path: "/", icon: Home },
    { name: "Mercado", path: "/market", icon: ShoppingBag },
    { name: "Listas", path: "/lists", icon: ListOrdered },
    ...(user
      ? [
          { name: "Amigos", path: "/friends", icon: Users },
          { name: "Seguimiento", path: "/market/tracking", icon: Bell },
          { name: "Perfil", path: "/profile", icon: UserIcon },
        ]
      : []),
  ];

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-100 font-sans">
      {/* Sidebar for Desktop */}
      <aside className="hidden md:flex flex-col w-64 bg-slate-900 border-r border-slate-800 fixed h-full z-20">
        <div className="p-6 border-b border-slate-800">
          <h1 className="text-2xl font-bold bg-gradient-to-r from-cyan-400 to-blue-600 bg-clip-text text-transparent">
            SteaMates
          </h1>
        </div>

        {user && (
          <div className="px-6 py-4 flex items-center gap-3 border-b border-slate-800/50">
            <img
              src={user.avatarfull}
              alt={user.personaname}
              className="w-10 h-10 rounded-full ring-2 ring-blue-500/50"
            />
            <div className="overflow-hidden">
              <p className="font-bold text-sm truncate flex items-center gap-1.5">
                <span className="truncate">{user.personaname}</span>
                {isWarnedUser && (
                  <span
                    title={warningTooltip}
                    aria-label={warningTooltip}
                    className="inline-flex shrink-0"
                  >
                    <AlertOctagon size={14} className="text-amber-400" />
                  </span>
                )}
                {isSilencedUser && (
                  <span
                    title={silencedTooltip}
                    aria-label={silencedTooltip}
                    className="inline-flex shrink-0"
                  >
                    <MessageSquareOff size={14} className="text-orange-400" />
                  </span>
                )}
              </p>
              <p className="text-xs text-green-400 flex items-center gap-1">
                <span className="w-1.5 h-1.5 bg-green-500 rounded-full"></span>{" "}
                Online
              </p>
            </div>
          </div>
        )}

        <nav className="flex-1 min-h-0 p-4 space-y-2 overflow-y-auto scrollbar-none overscroll-contain">
          {navItems.map((item) => {
            const isActive = location.pathname === item.path;
            const Icon = item.icon;
            return (
              <Link
                key={item.path}
                to={item.path}
                className={cn(
                  "flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200",
                  isActive
                    ? "bg-blue-600/20 text-blue-400 font-medium border border-blue-600/30"
                    : "text-slate-400 hover:bg-slate-800 hover:text-slate-200",
                )}
              >
                <Icon size={20} />
                <span>{item.name}</span>
              </Link>
            );
          })}

          {/* Notifications bell - only for logged in users */}
          {user && <NotificationBell />}

          {/* Admin Panel Link - Only for admins */}
          {isAdmin && (
            <Link
              to="/admin"
              className={cn(
                "flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 mt-4 border-t border-slate-800 pt-4",
                location.pathname === "/admin"
                  ? "bg-red-600/20 text-red-400 font-medium border border-red-600/30"
                  : "text-slate-400 hover:bg-slate-800 hover:text-slate-200",
              )}
            >
              <Shield size={20} />
              <span>Admin Panel</span>
            </Link>
          )}
        </nav>
        <div className="p-4 border-t border-slate-800">
          {user ? (
            <button
              onClick={logout}
              className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-red-400 hover:bg-slate-800/50 rounded-xl transition-colors cursor-pointer"
            >
              <LogOut size={20} />
              <span className="text-sm">Cerrar Sesión</span>
            </button>
          ) : !isLoginPage ? (
            <Link
              to="/login"
              className="flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-white hover:bg-blue-600/20 rounded-xl transition-colors border border-dashed border-slate-700 hover:border-blue-500/50 cursor-pointer"
            >
              <LogIn size={20} />
              <span className="text-sm">Iniciar Sesión</span>
            </Link>
          ) : (
            <div
              aria-hidden="true"
              className="invisible flex items-center gap-3 px-4 py-3 rounded-xl border border-dashed border-slate-700"
            >
              <LogIn size={20} />
              <span className="text-sm">Iniciar Sesión</span>
            </div>
          )}
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 w-full z-30 bg-slate-900/80 backdrop-blur-md border-b border-slate-800 flex items-center justify-between p-4">
        <h1 className="text-xl font-bold bg-gradient-to-r from-cyan-400 to-blue-600 bg-clip-text text-transparent">
          SteaMates
        </h1>
        <div className="flex items-center gap-4">
          {user && (
            <img src={user.avatarfull} className="w-8 h-8 rounded-full" />
          )}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="p-2 text-slate-300 hover:bg-slate-800 rounded-lg"
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu Overlay */}
      <AnimatePresence>
        {isMobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="fixed inset-0 z-20 bg-slate-950 pt-20 px-4 md:hidden overflow-y-auto"
          >
            <nav className="flex flex-col space-y-2">
              {navItems.map((item) => {
                const isActive = location.pathname === item.path;
                const Icon = item.icon;
                return (
                  <Link
                    key={item.path}
                    to={item.path}
                    onClick={() => setIsMobileMenuOpen(false)}
                    className={cn(
                      "flex items-center gap-3 px-4 py-4 rounded-xl text-lg",
                      isActive
                        ? "bg-blue-600/20 text-blue-400 border border-blue-600/30"
                        : "text-slate-400 hover:bg-slate-800",
                    )}
                  >
                    <Icon size={24} />
                    <span>{item.name}</span>
                  </Link>
                );
              })}

              {user && (
                <NotificationBell
                  variant="mobile"
                  buttonClassName="py-4 text-lg"
                />
