        <p className="text-sm font-medium text-slate-100 leading-tight">
          {n.title}
        </p>
        <p className="text-xs text-slate-400 mt-0.5 leading-snug line-clamp-2">
          {n.message}
        </p>
        <p className="text-xs text-slate-500 mt-1">{timeAgo(n.createdAt)}</p>
      </div>

      {/* Unread dot */}
      {isUnread && (
