import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine, Brush } from "recharts";
import { toast } from "sonner";
import api, {
  addWishlistItem,
  createPriceAlert,
  deletePriceAlert,
  getPriceAlerts,
  getWishlist,
