import {
  ArrowLeft,
  Lock,
  MessageSquare,
  Plus,
  Share2,
  ThumbsDown,
  ThumbsUp,
  Trash2,
} from "lucide-react";
import { Link, Navigate, useParams, useNavigate } from "react-router";
import { useAuth } from "../context/AuthContext";
import { useEffect, useState } from "react";
import api from "../../lib/api";
import { formatDistanceToNow } from "date-fns";
import { es } from "date-fns/locale";
import { ReportButton } from "../components/ReportButton";
import { UserProfileLink } from "../components/UserProfileLink";

interface Game {
  appId: string | number;
  name: string;
  imageUrl?: string;
  image?: string;
  _id: string;
}

interface CommentData {
  _id: string;
  content: string;
  author: {
    _id: string;
    steamId?: string;
    username: string;
    avatar: string;
  };
  createdAt: string;
}

interface List {
  _id: string;
  title: string;
  description: string;
  coverImage: string;
  author: {
    _id: string;
    steamId?: string;
    username: string;
    avatar: string;
  };
  games: Game[];
  likes: string[];
  dislikes: string[];
  createdAt: string;
}

export function ListDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user, login } = useAuth();
  const [list, setList] = useState<List | null>(null);
  const [comments, setComments] = useState<CommentData[]>([]);
  const [commentsPage, setCommentsPage] = useState(1);
  const [commentsHasMore, setCommentsHasMore] = useState(false);
  const [commentsLoadingMore, setCommentsLoadingMore] = useState(false);
  const [commentsTotal, setCommentsTotal] = useState(0);
  const [newComment, setNewComment] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  const handleDelete = async () => {
    if (!window.confirm("¿Estás seguro de que quieres borrar esta lista?")) return;
    try {
      await api.delete(`/api/lists/${id}`);
      navigate("/lists");
    } catch (err) {
      console.error("Error deleting list:", err);
      alert("Hubo un error al borrar la lista");
    }
  };

  useEffect(() => {
    const fetchListAndComments = async () => {
      try {
        const [listRes, commentsRes] = await Promise.all([
          api.get(`/api/lists/${id}`),
          api.get(`/api/lists/${id}/comments`, { params: { page: 1, limit: 12 } })
        ]);
        setList(listRes.data);
        
        // Handle both paginated and array responses
        const commentsList = Array.isArray(commentsRes.data)
          ? commentsRes.data
          : commentsRes.data?.comments || [];
        const commentsPagination = Array.isArray(commentsRes.data)
          ? null
          : commentsRes.data?.pagination || null;
        
        setComments(commentsList);
        setCommentsPage(commentsPagination?.page || 1);
        setCommentsTotal(commentsPagination?.total || commentsList.length);
        setCommentsHasMore(
          commentsPagination
            ? commentsPagination.page < commentsPagination.pages
            : false
        );
      } catch (err) {
        console.error("Error fetching list data:", err);
        setError(true);
      } finally {
        setLoading(false);
      }
    };
    if (id) {
      fetchListAndComments();
    }
  }, [id]);

  const handleLike = async () => {
    if (!user) return login();
    try {
      const res = await api.post(`/api/lists/${id}/like`);
      setList(prev => prev ? { ...prev, likes: res.data.likes, dislikes: res.data.dislikes } : prev);
    } catch (err) {
      console.error(err);
    }
  };

  const handleDislike = async () => {
    if (!user) return login();
    try {
      const res = await api.post(`/api/lists/${id}/dislike`);
      setList(prev => prev ? { ...prev, likes: res.data.likes, dislikes: res.data.dislikes } : prev);
    } catch (err) {
      console.error(err);
    }
  };

  const handlePostComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return login();
    if (!newComment.trim()) return;

    try {
      const res = await api.post(`/api/lists/${id}/comments`, { content: newComment });
      setComments([res.data, ...comments]);
      setCommentsTotal((prev) => prev + 1);
      setNewComment("");
    } catch (err) {
      console.error(err);
      const error = err as any;
      const errorMessage = error?.response?.data?.error || error?.message || "Unknown error";
      alert(`Error creating comment: ${errorMessage}`);
    }
  };

  const loadMoreComments = async () => {
    if (!id || commentsLoadingMore || loading || !commentsHasMore) return;

    try {
      setCommentsLoadingMore(true);
      const nextPage = commentsPage + 1;
      const response = await api.get(`/api/lists/${id}/comments`, {
        params: { page: nextPage, limit: 12 },
      });

      // Handle both paginated and array responses
      const nextComments = Array.isArray(response.data)
        ? response.data
        : response.data?.comments || [];
      const responsePagination = Array.isArray(response.data)
        ? null
        : response.data?.pagination || null;

      setComments((prev) => [...prev, ...nextComments]);
      setCommentsPage(responsePagination?.page || nextPage);
      setCommentsTotal(responsePagination?.total || commentsTotal);
      setCommentsHasMore(
        responsePagination
          ? responsePagination.page < responsePagination.pages
          : false
      );
    } catch (err) {
      console.error("Error loading more comments:", err);
    } finally {
      setCommentsLoadingMore(false);
    }
  };

  if (loading) {
    return <div className="text-white text-center py-20">Cargando...</div>;
  }

  if (error || !list) {
    return <Navigate to="/lists" replace />;
  }

  return (
    <div className="pb-20">
      <Link
        to="/lists"
        className="inline-flex items-center gap-2 text-[#90a1b9] hover:text-white text-[16px]"
      >
        <ArrowLeft size={20} /> Volver a Listas
      </Link>

      <article className="mt-6 rounded-2xl border border-[#1d293d] bg-[#0f172b] overflow-hidden shadow-[0px_25px_50px_-12px_rgba(0,0,0,0.25)]">
        <header className="relative h-[220px] sm:h-[256px] bg-[#1d293d]">
          <img
            src={list.coverImage || "https://images.unsplash.com/photo-1542751371-adc38448a05e?q=80&w=2070"}
            alt={list.title}
            className="absolute inset-0 w-full h-full object-cover opacity-50"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-[#0f172b] to-transparent" />

          <div className="absolute inset-x-4 bottom-4 sm:inset-x-10 sm:bottom-10 flex flex-col lg:flex-row lg:items-end lg:justify-between gap-4">
            <div>
              <h1 className="text-white text-[26px] sm:text-[36px] leading-[32px] sm:leading-[40px] font-bold">
                {list.title}
              </h1>
              <div className="mt-2 flex flex-wrap items-center gap-3 text-[13px] sm:text-[16px]">
                <UserProfileLink
                  steamId={list.author?.steamId || list.author?._id}
                  username={list.author?.username || 'Unknown'}
                  avatar={list.author?.avatar}
                  variant="both"
                  avatarClassName="w-8 h-8 rounded-full border border-[#45556c] bg-[#314158]"
                  nameClassName="text-white"
                />
                <span className="text-[#62748e]">•</span>
                <span className="text-[#cad5e2]">
                  {formatDistanceToNow(new Date(list.createdAt), {
                    addSuffix: true,
                    locale: es,
                  })}
                </span>
              </div>
            </div>

            <div className="h-auto sm:h-[54px] rounded-[14px] border border-[rgba(255,255,255,0.1)] bg-[rgba(2,6,24,0.5)] px-3 py-2 sm:py-0 flex flex-wrap items-center gap-3 w-full sm:w-fit">
              <button 
                onClick={handleLike}
                className={`h-9 rounded-[10px] px-3 flex items-center gap-2 hover:bg-[#1d293d] transition-colors text-[16px] font-bold ${list.likes?.includes(user?.id || '') ? 'text-[#00d492]' : 'text-[#62748e]'}`}
              >
                <ThumbsUp size={18} /> {list.likes?.length || 0}
              </button>
              <div className="w-px h-6 bg-[#314158]" />
              <button 
                onClick={handleDislike}
                className={`h-9 rounded-[10px] px-3 flex items-center gap-2 hover:bg-[#1d293d] transition-colors text-[16px] font-bold ${list.dislikes?.includes(user?.id || '') ? 'text-[#ff6467]' : 'text-[#62748e]'}`}
              >
                <ThumbsDown size={18} /> {list.dislikes?.length || 0}
              </button>
            </div>
          </div>
        </header>

        <section className="border-b border-[#1d293d] px-4 sm:px-6 md:px-10 py-8 sm:py-10">
          <p className="text-[#cad5e2] text-[18px] leading-[29px] whitespace-pre-wrap">
            {list.description}
          </p>

          <div className="mt-6 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div className="flex flex-wrap items-center gap-4">
              <button
                type="button"
                className="inline-flex items-center gap-2 text-[#90a1b9] text-[16px]"
              >
                <MessageSquare size={20} /> {commentsTotal || comments.length} Comentarios
              </button>
            </div>

            <div className="flex flex-wrap items-center gap-4">
              {user && user.id !== String(list.author?._id) && (
                <ReportButton
                  targetId={list._id}
                  targetType="list"
                  buttonLabel="Reportar lista"
                  buttonClassName="inline-flex items-center gap-2 text-[#90a1b9] text-[16px] hover:text-[#ff8a8c] transition-colors"
                />
              )}
              {user && user.id === String(list.author?._id) && (
                <button
                  type="button"
                  onClick={handleDelete}
                  className="inline-flex items-center gap-2 text-[#ff6467] text-[16px] hover:text-[#ff8a8c] transition-colors"
                >
                  <Trash2 size={20} /> Borrar lista
                </button>
              )}
              <button
                type="button"
                onClick={() => {
                  navigator.clipboard.writeText(window.location.href);
                  alert("!Enlace copiado al portapapeles!");
                }}
                className="inline-flex items-center gap-2 text-[#90a1b9] text-[16px] hover:text-white transition-colors"
              >
                <Share2 size={20} /> Compartir
              </button>
            </div>
          </div>
        </section>

        <section className="bg-[rgba(2,6,24,0.3)] px-4 sm:px-6 md:px-10 py-8 sm:py-10">
          <div className="flex items-center gap-2 mb-6">
            <span className="w-8 h-8 rounded-[10px] bg-[#4f39f6] inline-flex items-center justify-center text-white text-[14px] font-bold">
              {list.games.length}
            </span>
            <h2 className="text-white text-[20px] leading-7 font-bold">
              Juegos en esta coleccion
            </h2>
          </div>

          <div className="space-y-4">
            {list.games.map((game, index) => (
              <div
                key={game._id}
                className="rounded-[14px] border border-[#1d293d] bg-[#0f172b] p-4 flex flex-col sm:flex-row sm:items-center gap-4"
              >
                <div className="text-[#314158] text-[24px] leading-8 font-bold w-10 text-center shrink-0">
                  #{index + 1}
                </div>
                <div className="relative w-full sm:w-[192px] h-[118px] rounded-[10px] overflow-hidden bg-[#1d293d] shrink-0">
                  <img
                    src={game.imageUrl || game.image || `https://picsum.photos/seed/${game.name}/200/100`}
                    alt={game.name}
                    className="absolute inset-0 w-full h-full object-cover"
                  />
                </div>
                <div className="min-w-0 flex-1">
                  <h3 className="text-white text-[20px] leading-7 font-bold truncate">
                    {game.name}
                  </h3>
                </div>
              </div>
            ))}
          </div>
        </section>

        <section className="border-t border-[#1d293d] px-4 sm:px-6 md:px-10 py-8 sm:py-10">
          <h2 className="text-white text-[20px] leading-7 font-bold mb-6">
            Comentarios ({commentsTotal || comments.length})
          </h2>

          {!user ? (
            <div className="rounded-[14px] border border-[#1d293d] bg-[rgba(2,6,24,0.5)] p-6 text-center">
              <Lock size={32} className="text-[#62748e] mx-auto" />
              <p className="mt-3 text-[#90a1b9] text-[16px] leading-6">
                Debes iniciar sesión para comentar
              </p>
              <button
                type="button"
                onClick={login}
                className="mt-4 h-9 rounded-[10px] bg-[#4f39f6] px-4 text-white text-[14px] font-medium"
              >
                Iniciar Sesión
              </button>
            </div>
          ) : (
            <form onSubmit={handlePostComment} className="flex flex-col sm:flex-row gap-4 mb-8">
              <img
                src={user.avatarfull}
                alt={user.personaname}
                className="w-10 h-10 rounded-full object-cover ring-2 ring-[#1d293d] shrink-0"
              />
              <div className="flex-1">
                <textarea
                  value={newComment}
                  onChange={(e) => setNewComment(e.target.value)}
                  placeholder="Escribe un comentario..."
                  className="w-full rounded-[10px] border border-[#1d293d] bg-[rgba(2,6,24,0.5)] px-4 py-3 text-white placeholder-[#62748e] focus:outline-none focus:border-[#4f39f6] resize-none h-24"
                />
                <button
                  type="submit"
                  disabled={!newComment.trim()}
                  className="mt-3 h-9 rounded-[10px] bg-[#4f39f6] px-6 text-white text-[14px] font-medium disabled:opacity-50 disabled:cursor-not-allowed hover:bg-[#4330d3] transition-colors"
                >
                  Comentar
                </button>
              </div>
            </form>
          )}

          <div className="mt-8 space-y-6">
            {comments.map((comment) => (
              <div key={comment._id} className="flex items-start gap-4">
                <UserProfileLink
                  steamId={comment.author?.steamId || comment.author?._id}
                  username={comment.author?.username || 'Unknown'}
                  avatar={comment.author?.avatar}
                  variant="avatar"
                  avatarClassName="w-10 h-10 rounded-full object-cover ring-2 ring-[#1d293d] shrink-0 bg-[#1d293d]"
                />

                <div className="min-w-0 flex-1">
                  <div className="rounded-tl-[2px] rounded-tr-[14px] rounded-br-[14px] rounded-bl-[14px] bg-[rgba(29,41,61,0.5)] px-4 py-3 border border-[#1d293d]">
                    <div className="flex items-center justify-between gap-3">
                      <div className="flex items-center gap-3 min-w-0">
                        <UserProfileLink
                          steamId={comment.author?.steamId || comment.author?._id}
                          username={comment.author?.username || 'Unknown'}
                          variant="name"
                          nameClassName="text-white text-[16px] leading-6 font-bold truncate"
                        />
                        {user && user.id !== String(comment.author?._id) && (
                          <ReportButton
                            targetId={comment._id}
                            targetType="comment"
                            buttonLabel="Reportar"
                            buttonClassName="inline-flex items-center gap-1 text-[#90a1b9] text-[12px] hover:text-[#ff8a8c] transition-colors"
                          />
                        )}
                      </div>
                      <span className="text-[#62748e] text-[12px] leading-4 whitespace-nowrap">
                        {formatDistanceToNow(new Date(comment.createdAt), {
                          addSuffix: true,
                          locale: es,
                        })}
                      </span>
                    </div>
                    <p className="mt-1 text-[#cad5e2] text-[14px] leading-5 whitespace-pre-wrap">
                      {comment.content}
                    </p>
                  </div>
                </div>
              </div>
            ))}

            {commentsHasMore && (
              <div className="flex justify-center pt-2">
                <button
                  type="button"
                  onClick={loadMoreComments}
                  disabled={commentsLoadingMore}
                  className="px-5 py-2.5 rounded-[10px] bg-[#155dfc] text-white text-[14px] font-medium hover:bg-[#1d66ff] transition-colors disabled:opacity-60"
                >
                  {commentsLoadingMore ? "Cargando..." : "Cargar más comentarios"}
                </button>
              </div>
            )}
          </div>
        </section>
      </article>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Bookmark,
  Check,
  ChevronLeft,
  ChevronRight,
  Clock3,
  Eye,
  Flame,
  GripVertical,
  Heart,
  MessageSquare,
  Plus,
  Search,
  Sparkles,
  Star,
  X,
} from "lucide-react";
import { Link } from "react-router";
import { CATEGORY_CHIPS, FEED_TABS, FeedTab } from "../data/communityLists";
import api from "../../lib/api";

type CreateGameOption = {
  id: string;
  title: string;
  year: string;
  price: string;
  score: string;
  image: string;
};

export function Lists() {
  const [feedTab, setFeedTab] = useState<FeedTab>("trending");
  const [selectedCategory, setSelectedCategory] = useState("Todas");
  const [query, setQuery] = useState("");
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);

  // Real Lists from backend
  const [lists, setLists] = useState<any[]>([]);
  const [loadingLists, setLoadingLists] = useState(true);
  const [loadingMoreLists, setLoadingMoreLists] = useState(false);
  const [listsPage, setListsPage] = useState(1);
  const [listsHasMore, setListsHasMore] = useState(false);
  const [listsLoadError, setListsLoadError] = useState("");

  // Steam Game Search
  const [searchGamesOptions, setSearchGamesOptions] = useState<
    CreateGameOption[]
  >([]);
  const [isSearchingGames, setIsSearchingGames] = useState(false);

  const [createStep, setCreateStep] = useState<1 | 2 | 3>(1);
  const [createTitle, setCreateTitle] = useState("");
  const [createDescription, setCreateDescription] = useState("");
  const [createCategories, setCreateCategories] = useState<string[]>([]);
  const [createCover, setCreateCover] = useState(
    () =>
      "https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&q=80&w=800",
  );
  const [createGameQuery, setCreateGameQuery] = useState("");
  const [createSelectedGames, setCreateSelectedGames] = useState<
    CreateGameOption[]
  >([]);

  const fetchLists = async (page = 1, append = false) => {
    try {
      if (append) {
        setLoadingMoreLists(true);
      } else {
        setLoadingLists(true);
      }

      setListsLoadError("");
      const res = await api.get('/api/lists', {
        params: {
          page,
          limit: 12,
        },
      });

      const responseLists = Array.isArray(res.data)
        ? res.data
        : res.data?.lists || [];
      const responsePagination = Array.isArray(res.data)
        ? null
        : res.data?.pagination || null;

      const nextLists = responseLists;
      setLists((prev) => (append ? [...prev, ...nextLists] : nextLists));
      setListsPage(responsePagination?.page || page);
      setListsHasMore(
        responsePagination
          ? responsePagination.page < responsePagination.pages
          : false,
      );
    } catch (err) {
      console.error("Error fetching lists:", err);
      if (!append) {
        setLists([]);
      }
      setListsHasMore(false);
      setListsLoadError("No se pudieron cargar las listas.");
    } finally {
      setLoadingLists(false);
      setLoadingMoreLists(false);
    }
  };

  useEffect(() => {
    fetchLists(1, false);
  }, []);

  const loadMoreLists = () => {
    if (loadingMoreLists || loadingLists || !listsHasMore) return;
    fetchLists(listsPage + 1, true);
  };

  useEffect(() => {
    const delayDebounceFn = setTimeout(async () => {
      if (createGameQuery.trim().length > 2) {
        setIsSearchingGames(true);
        try {
          const res = await api.get(
            `/api/steam/search?term=${encodeURIComponent(createGameQuery)}`,
          );
          const results = res.data.map((item: any) => {
            const appId = item.appId ? item.appId.toString() : null;

            // Backend now returns isFree (boolean) and price (number in dollars)
            const isFree = item.isFree === true || item.price === 0;
            const priceLabel = isFree
              ? "Gratis"
              : `$${Number(item.price).toFixed(2)}`;

            // Image via Steam CDN
            const image = appId
              ? `https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/${appId}/header.jpg`
              : `https://placehold.co/80x80/1e293b/94a3b8?text=${encodeURIComponent(item.name?.[0] ?? "?")}`;

            return {
              id: appId || item.name,
              title: item.name,
              year: "—",
              price: priceLabel,
              score: "-",
              image,
            };
          });
          setSearchGamesOptions(results);
        } catch (err) {
          console.error("Error searching games:", err);
        } finally {
          setIsSearchingGames(false);
        }
      } else {
        setSearchGamesOptions([]);
      }
    }, 500); // 500ms debounce

    return () => clearTimeout(delayDebounceFn);
  }, [createGameQuery]);

  const createCategoryOptions = useMemo(
    () => CATEGORY_CHIPS.filter((chip) => chip !== "Todas"),
    [],
  );

  const createCoverOptions = useMemo(
    () => [
      {
        id: "cover1",
        title: "Gaming Setup",
        image:
          "https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&q=80&w=800",
      },
      {
        id: "cover2",
        title: "Retro Arcade",
        image:
          "https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&q=80&w=800",
      },
      {
        id: "cover3",
        title: "Abstract Data",
        image:
          "https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&q=80&w=800",
      },
    ],
    [],
  );

  const titleChars = createTitle.length;
  const descriptionChars = createDescription.length;
  const canContinueInfo =
    createTitle.trim().length > 0 &&
    createDescription.trim().length > 0 &&
    createCategories.length > 0 &&
    createCover.length > 0;
  const canContinueGames = createSelectedGames.length > 0;

  const closeCreateModal = () => {
    setIsCreateModalOpen(false);
    setCreateStep(1);
    setCreateGameQuery("");
  };

  const [isSubmitting, setIsSubmitting] = useState(false);

  const submitList = async () => {
    try {
      setIsSubmitting(true);
      const payload = {
        title: createTitle,
        description: createDescription,
        categories: createCategories,
        coverImage: createCover,
        games: createSelectedGames.map((g, index) => ({
          appId: parseInt(g.id, 10) || index + 1,
          name: g.title,
          imageUrl: g.image,
        })),
      };

      const res = await api.post("/api/lists", payload);
      console.log("List created successfully:", res.data);

      // Clean up fields
      setCreateTitle("");
      setCreateDescription("");
      setCreateSelectedGames([]);
      closeCreateModal();

      // Reload lists
      fetchLists(1, false);
    } catch (err: any) {
      console.error("Error creating list:", err);
      const errorMessage =
        err.response?.data?.error || err.message || "Unknown error";
      alert(`Error creating list: ${errorMessage}`);
    } finally {
      setIsSubmitting(false);
    }
  };

  const addGameToSelection = (game: CreateGameOption) => {
    setCreateSelectedGames((prev) => {
      if (prev.some((item) => item.id === game.id)) {
        return prev;
      }
      return [...prev, game];
    });
  };

  const removeGameFromSelection = (gameId: string) => {
    setCreateSelectedGames((prev) => prev.filter((game) => game.id !== gameId));
  };

  useEffect(() => {
    if (!isCreateModalOpen) {
      return;
    }

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    return () => {
      document.body.style.overflow = previousOverflow;
    };
  }, [isCreateModalOpen]);

  useEffect(() => {
    if (!isCreateModalOpen) {
      return;
    }

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        closeCreateModal();
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [isCreateModalOpen]);

  const filteredCreateGameOptions = useMemo(() => {
    const selectedIds = new Set(createSelectedGames.map((game) => game.id));
    return searchGamesOptions.filter((game) => !selectedIds.has(game.id));
  }, [searchGamesOptions, createSelectedGames]);

  const previewCategoryLabel = useMemo(() => {
    const iconByCategory: Record<string, string> = {
      RPG: "⚔️",
      "Co-op": "🤝",
      Indie: "🎨",
      Ofertas: "💰",
      Terror: "👻",
      Estrategia: "🧠",
      Retro: "🕹️",
      Simulacion: "🏗️",
      "Sci-Fi": "🚀",
      Accion: "💥",
    };

    if (createCategories.length === 0) return "Sin Categoría";
    const primary = createCategories[0];
    const icon = iconByCategory[primary] ?? "🎮";
    const extra =
      createCategories.length > 1 ? ` +${createCategories.length - 1}` : "";
    return `${icon} ${primary}${extra}`;
  }, [createCategories]);

  const filteredLists = useMemo(() => {
    const q = query.trim().toLowerCase();

    // Get current user robustly to prevent json parse errors
    const currentUserStr = localStorage.getItem("steamates_user");
    let currentUser = null;
    try {
      if (currentUserStr) currentUser = JSON.parse(currentUserStr);
    } catch (e) {
      console.error(e);
    }

    const result = lists.filter((item) => {
      const isMine = currentUser
        ? currentUser.steamid === item.author?.steamId
        : false;

      const matchesTab =
        feedTab === "trending"
          ? true // Can logic this out later based on likes
          : feedTab === "new"
            ? true // Sort by created At later
            : feedTab === "top"
              ? true // Sort by likes later
              : isMine;

      const matchesCategory =
        selectedCategory === "Todas" ||
        (item.categories &&
          item.categories.some(
            (c: string) => c.toLowerCase() === selectedCategory.toLowerCase(),
          ));

      const matchesQuery =
        q.length === 0 ||
        item.title.toLowerCase().includes(q) ||
        (item.author?.username || "").toLowerCase().includes(q) ||
        (item.description || "").toLowerCase().includes(q);

      return matchesTab && matchesCategory && matchesQuery;
    });

    if (feedTab === "new") {
      return result.sort(
        (a, b) =>
          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
      );
    }

    if (feedTab === "top" || feedTab === "trending") {
      return result.sort(
        (a, b) => (b.likes?.length || 0) - (a.likes?.length || 0),
      );
    }

    return result;
  }, [lists, feedTab, query, selectedCategory]);

  return (
    <div className="pb-20 space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-[28px] sm:text-[36px] lg:text-[42px] leading-[1.1] font-bold text-white mb-2">
            Listas de la Comunidad
          </h1>
          <p className="text-[#90a1b9] text-[14px]">
            Descubre colecciones curadas por otros jugadores
          </p>
        </div>

        <button
          className="h-10 w-full sm:w-auto justify-center px-4 rounded-[10px] bg-[#009966] text-white text-[14px] font-medium flex items-center gap-2 hover:bg-[#00ad74] transition-colors self-start"
          type="button"
          onClick={() => {
            setCreateStep(1);
            setIsCreateModalOpen(true);
          }}
        >
          <Plus size={18} /> Crear Lista
        </button>
      </div>

      <div className="space-y-4">
        <div className="flex flex-col xl:flex-row xl:items-center xl:justify-between gap-3">
          <div className="h-auto sm:h-[42px] p-[5px] rounded-[14px] border border-[#1d293d] bg-[rgba(15,23,43,0.8)] flex flex-wrap items-start gap-1 w-fit">
            {FEED_TABS.map((tab) => {
              const active = feedTab === tab.id;
              return (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setFeedTab(tab.id)}
                  className={`h-8 rounded-[10px] px-4 text-[12px] font-medium flex items-center gap-2 transition-all ${
                    active
                      ? "bg-[#155dfc] text-white shadow-[0px_10px_15px_0px_rgba(43,127,255,0.2)]"
                      : "text-[#90a1b9] hover:text-white"
                  }`}
                >
                  {tab.id === "trending" && <Flame size={14} />}
                  {tab.id === "top" && <Star size={14} />}
                  {tab.id === "new" && <Clock3 size={14} />}
                  {tab.id === "mine" && <Bookmark size={14} />}
                  {tab.label}
                </button>
              );
            })}
          </div>

          <div className="relative w-full xl:w-[256px]">
            <Search
              size={14}
              className="absolute left-3 top-1/2 -translate-y-1/2 text-[#62748e]"
            />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Buscar listas..."
              className="w-full h-[38px] rounded-[10px] bg-[#0f172b] border border-[#314158] pl-9 pr-4 text-[14px] text-[#cad5e2] placeholder:text-[rgba(226,232,240,0.5)] focus:outline-none focus:border-[#51a2ff]"
            />
          </div>
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-1">
          {CATEGORY_CHIPS.map((chip) => {
            const active = chip === selectedCategory;
            return (
              <button
                key={chip}
                type="button"
                onClick={() => setSelectedCategory(chip)}
                className={`h-[30.5px] rounded-full px-[13px] text-[11px] font-medium whitespace-nowrap border transition-colors ${
                  active
                    ? "bg-[#155dfc] border-[#2b7fff] text-white"
                    : "bg-[#0f172b] border-[#314158] text-[#90a1b9] hover:text-white"
                }`}
              >
                {chip}
              </button>
            );
          })}
        </div>

        {loadingLists ? (
          <div className="flex items-center justify-center p-20 text-[#cad5e2]">
            Cargando listas...
          </div>
        ) : listsLoadError ? (
          <div className="bg-[rgba(15,23,43,0.8)] border border-[#1d293d] rounded-[14px] p-10 text-center">
            <p className="text-[#ff8a8c] text-[14px] mb-4">
              {listsLoadError}
            </p>
            <button
              type="button"
              onClick={() => fetchLists(1, false)}
              className="h-9 px-4 rounded-[10px] bg-[#155dfc] text-white text-[13px] font-medium"
            >
              Reintentar
            </button>
          </div>
        ) : filteredLists.length > 0 ? (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-5">
              {filteredLists.map((list) => (
                <Link
                  key={list._id}
                  to={`/lists/${list._id}`}
                  className="bg-[#0f172b] border border-[#1d293d] rounded-[14px] overflow-hidden block hover:border-[#2b7fff] transition-colors"
                >
                  <div className="relative h-[160px]">
                    <img
                      src={list.coverImage}
                      alt={list.title}
                      className="absolute inset-0 w-full h-full object-cover"
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-[#0f172b] via-[rgba(15,23,43,0.4)] to-transparent" />

                    <div className="absolute top-3 left-3 flex items-center gap-1.5">
                      {(localStorage.getItem('steamates_user') && (() => {
                        try {
                          return JSON.parse(localStorage.getItem('steamates_user')!).steamid === list.author?.steamId;
                        } catch { return false; }
                      })()) && (
                        <span className="h-[19px] rounded-full px-2 bg-[rgba(43,127,255,0.9)] text-white text-[10px] font-bold">
                          TUYA
                        </span>
                      )}
                    </div>

                    <span
                      className="absolute top-4 right-3 h-5 rounded-full border px-[9px] text-[10px] font-medium flex items-center border-[rgba(43,127,255,0.2)] bg-[rgba(43,127,255,0.15)] text-[#51a2ff]"
                    >
                      {list.categories && list.categories[0] ? list.categories[0] : 'General'}
                    </span>

                    <div className="absolute left-4 right-4 bottom-3">
                      <h3 className="text-white text-[22px] leading-6 font-bold mb-0.5 truncate">
                        {list.title}
                      </h3>
                      <p className="text-[11px] text-[#cad5e2]">
                        por <span className="text-[#51a2ff]">{list.author?.username || 'Usuario Desconocido'}</span>
                      </p>
                    </div>
                  </div>

                  <div className="p-4 pt-3">
                    <p className="text-[#90a1b9] text-[12px] leading-[19.5px] min-h-[58px] line-clamp-3">
                      {list.description}
                    </p>

                    <div className="mt-4 pt-2 border-t border-[#1d293d] flex items-center justify-between">
                      <div className="flex items-center gap-3 text-[#62748e] text-[12px]">
                        <span className="flex items-center gap-1">
                          <Heart size={13} /> {list.likes?.length || 0}
                        </span>
                        <span className="flex items-center gap-1">
                          <MessageSquare size={13} /> {list.commentsCount || 0}
                        </span>
                      </div>
                      <span className="h-[17px] rounded-[4px] bg-[#1d293d] px-2 text-[#62748e] text-[10px] font-medium flex items-center">
                        {list.games?.length || 0} juegos
                      </span>
                    </div>
                  </div>
                </Link>
              ))}
            </div>

          </>
        ) : (
          <div className="bg-[rgba(15,23,43,0.8)] border border-[#1d293d] rounded-[14px] p-10 text-center">
            <p className="text-[#90a1b9] text-[14px] mb-4">
              No se encontraron listas para este filtro.
            </p>
            <button
              type="button"
              onClick={() => {
                setFeedTab("trending");
                setSelectedCategory("Todas");
                setQuery("");
              }}
              className="h-9 px-4 rounded-[10px] bg-[#155dfc] text-white text-[13px] font-medium"
            >
              Limpiar filtros
            </button>
          </div>
        )}

        {listsHasMore && (
          <div className="flex justify-center pt-4">
            <button
              onClick={loadMoreLists}
              disabled={loadingMoreLists}
              className="h-10 px-5 rounded-[10px] bg-[#155dfc] text-white text-[14px] font-medium flex items-center gap-2 hover:bg-[#1d66ff] transition-colors disabled:opacity-60"
            >
              {loadingMoreLists ? (
                <><span className="animate-spin">⏳</span> Cargando...</>
              ) : (
                "Cargar más"
              )}
            </button>
          </div>
        )}
      </div>

      {isCreateModalOpen && (
        <div
          className="fixed inset-0 z-40 bg-[rgba(2,6,24,0.78)] backdrop-blur-[2px] px-4 py-8 overflow-y-auto"
          onClick={closeCreateModal}
        >
          <div
            className="mx-auto w-full max-w-[672px] rounded-[16px] border border-[#1e2c46] bg-[#020b22] shadow-[0px_30px_70px_0px_rgba(0,0,0,0.55)] overflow-hidden"
            onClick={(event) => event.stopPropagation()}
          >
            <div className="px-6 pt-6 pb-4 bg-[linear-gradient(90deg,rgba(21,93,252,0.2)_0%,rgba(79,57,246,0.2)_50%,rgba(152,16,250,0.2)_100%)] border-b border-[#1e2c46]">
              <div className="flex items-start justify-between gap-3">
                <div>
                  <h2 className="text-[20px] leading-none font-semibold text-white flex items-center gap-2">
                    <Sparkles size={18} className="text-[#3cb5ff]" />
                    Crear Nueva Lista
                  </h2>
                  <p className="mt-2 text-[14px] text-[#90a1b9]">
                    Comparte tu coleccion curada con la comunidad
                  </p>
                </div>

                <button
                  type="button"
                  className="h-7 w-7 rounded-full text-[#6f7d94] hover:text-white hover:bg-[rgba(255,255,255,0.08)] transition-colors flex items-center justify-center"
                  onClick={closeCreateModal}
                  aria-label="Cerrar modal"
                >
                  <X size={16} />
                </button>
              </div>

              <div className="mt-5 flex items-center gap-2 text-[12px]">
                <div className="flex items-center gap-2">
                  <span
                    className={`h-7 w-7 rounded-full flex items-center justify-center text-[11px] font-semibold ${
                      createStep === 1
                        ? "bg-[#2b7fff] text-white"
                        : "bg-[#00bc7d] text-white"
                    }`}
                  >
                    {createStep === 1 ? "1" : <Check size={14} />}
                  </span>
                  <span
                    className={`font-medium ${
                      createStep === 1 ? "text-white" : "text-[#62748e]"
                    }`}
                  >
                    Info
                  </span>
                </div>
                <div
                  className={`h-px flex-1 ${
                    createStep >= 2
                      ? "bg-[rgba(0,188,125,0.5)]"
                      : "bg-[#40517b]"
                  }`}
                />
                <div className="flex items-center gap-2">
                  <span
                    className={`h-7 w-7 rounded-full flex items-center justify-center text-[11px] font-semibold ${
                      createStep === 2
                        ? "bg-[#2b7fff] text-white"
                        : createStep === 3
                          ? "bg-[#00bc7d] text-white"
                          : "bg-[#253353] text-[#62748e]"
                    }`}
                  >
                    {createStep === 3 ? <Check size={14} /> : "2"}
                  </span>
                  <span
                    className={`font-medium ${
                      createStep === 2 ? "text-white" : "text-[#62748e]"
                    }`}
                  >
                    Juegos
                  </span>
                </div>
                <div
                  className={`h-px flex-1 ${
                    createStep === 3
                      ? "bg-[rgba(0,188,125,0.5)]"
                      : "bg-[#2a3554]"
                  }`}
                />
                <div
                  className={`flex items-center gap-2 ${
                    createStep === 3
                      ? "text-white"
                      : "text-[#5f6f8f] opacity-40"
                  }`}
                >
                  <span
                    className={`h-7 w-7 rounded-full flex items-center justify-center text-[11px] font-semibold ${
                      createStep === 3
                        ? "bg-[#2b7fff] text-white"
                        : "bg-[#253353] text-[#62748e]"
                    }`}
                  >
                    3
                  </span>
                  <span>Vista previa</span>
                </div>
              </div>
            </div>

            {createStep === 1 ? (
              <>
                <div className="px-6 py-6 space-y-6">
                  <div>
                    <div className="mb-2 flex items-center justify-between text-[14px]">
                      <label
                        htmlFor="list-title"
                        className="text-[#cad5e2] font-medium"
                      >
                        Titulo de la lista{" "}
                        <span className="text-[#ff5f6d]">*</span>
                      </label>
                      <span className="text-[#62748e] text-[12px]">
                        {titleChars}/80
                      </span>
                    </div>
                    <input
                      id="list-title"
                      value={createTitle}
                      onChange={(event) =>
                        setCreateTitle(event.target.value.slice(0, 80))
                      }
                      placeholder="Ej: Top RPGs de todos los tiempos"
                      className="w-full h-11 rounded-[10px] bg-[#0f1f3b] border border-[#2f405e] px-4 text-[14px] text-[#cad5e2] placeholder:text-[#62748e] focus:outline-none focus:border-[#2b7fff]"
                    />
                  </div>

                  <div>
                    <div className="mb-2 flex items-center justify-between text-[14px]">
                      <label
                        htmlFor="list-description"
                        className="text-[#cad5e2] font-medium"
                      >
                        Descripcion
                      </label>
                      <span className="text-[#62748e] text-[12px]">
                        {descriptionChars}/200
                      </span>
                    </div>
                    <textarea
                      id="list-description"
                      value={createDescription}
                      onChange={(event) =>
                        setCreateDescription(event.target.value.slice(0, 200))
                      }
                      placeholder="Cuentale a la comunidad de que va tu lista..."
                      className="w-full h-[96px] rounded-[12px] bg-[#0f1f3b] border border-[#2f405e] px-4 py-3 text-[14px] text-[#cad5e2] placeholder:text-[#62748e] focus:outline-none focus:border-[#2b7fff] resize-none"
                    />
                  </div>

                  <div>
                    <p className="mb-2 text-[14px] text-[#cad5e2] font-medium">
                      Categoria <span className="text-[#ff5f6d]">*</span>
                    </p>
                    <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                      {createCategoryOptions.map((option) => {
                        const active = createCategories.includes(option);
                        return (
                          <button
                            key={option}
                            type="button"
                            onClick={() => {
                              setCreateCategories((prev) =>
                                prev.includes(option)
                                  ? prev.filter((c) => c !== option)
                                  : [...prev, option],
                              );
                            }}
                            className={`h-[50px] rounded-[10px] border text-[12px] transition-colors ${
                              active
                                ? "bg-[#1a3770] border-[#2b7fff] text-white"
                                : "bg-[#111f3a] border-[#2f405e] text-[#a7b6cd] hover:text-white"
                            }`}
                          >
                            {option}
                          </button>
                        );
                      })}
                    </div>
                  </div>

                  <div>
                    <p className="mb-2 text-[14px] text-[#cad5e2] font-medium">
                      Portada
                    </p>
                    <div className="grid grid-cols-1 sm:grid-cols-4 gap-2">
                      <label className="relative h-[88px] rounded-[10px] overflow-hidden border border-[#2f405e] hover:border-[#4766a3] transition-colors flex flex-col items-center justify-center cursor-pointer bg-[#0f172a]">
                        <Plus size={20} className="text-[#a7b6cd] mb-1" />
                        <span className="text-[#a7b6cd] text-[12px] font-medium">
                          Subir foto
                        </span>
                        <input
                          type="file"
                          accept="image/png, image/jpeg"
                          className="hidden"
                          onChange={(e) => {
                            const file = e.target.files?.[0];
                            if (file) {
                              const reader = new FileReader();
                              reader.onloadend = () => {
                                setCreateCover(reader.result as string);
                              };
                              reader.readAsDataURL(file);
                            }
                          }}
                        />
                      </label>
                      {createCoverOptions.map((cover) => {
                        const active = createCover === cover.image;
                        return (
                          <button
                            key={cover.id}
                            type="button"
                            onClick={() => setCreateCover(cover.image)}
                            className={`relative h-[88px] rounded-[10px] overflow-hidden border transition-colors ${
                              active
                                ? "border-[#2b7fff]"
                                : "border-[#2f405e] hover:border-[#4766a3]"
                            }`}
                            aria-label={`Seleccionar portada ${cover.title}`}
                          >
                            <img
                              src={cover.image}
                              alt={cover.title}
                              className="absolute inset-0 h-full w-full object-cover"
                            />
                            <div className="absolute inset-0 bg-gradient-to-t from-[rgba(1,8,22,0.85)] to-transparent" />
                            {active && (
                              <span className="absolute top-2 right-2 h-5 w-5 rounded-full bg-[#2b7fff] flex items-center justify-center text-white">
                                <Check size={12} />
                              </span>
                            )}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                </div>

                <div className="px-6 py-4 border-t border-[#1e2c46] bg-[rgba(2,6,24,0.8)] flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                  <button
                    type="button"
                    onClick={closeCreateModal}
                    className="h-10 w-full sm:w-auto justify-center px-3 rounded-[10px] text-[#a3b3cb] text-[14px] flex items-center gap-2 hover:text-white transition-colors"
                  >
                    <ChevronLeft size={14} /> Cancelar
                  </button>

                  <button
                    type="button"
                    onClick={() => setCreateStep(2)}
                    disabled={!canContinueInfo}
                    className={`h-10 w-full sm:w-auto justify-center px-5 rounded-[14px] text-[14px] font-medium flex items-center gap-2 transition-colors ${
                      canContinueInfo
                        ? "bg-[#155dfc] text-white hover:bg-[#2b7fff]"
                        : "bg-[#1c2f5c] text-[#6c84b3] cursor-not-allowed"
                    }`}
                  >
                    Siguiente <ChevronRight size={14} />
                  </button>
                </div>
              </>
            ) : createStep === 2 ? (
              <>
                <div className="px-6 py-5 space-y-4">
                  <div>
                    <p className="text-[14px] font-medium text-[#cad5e2] mb-2">
                      Tu seleccion ({createSelectedGames.length})
                    </p>
                    <div className="space-y-2 max-h-[192px] overflow-y-auto pr-1">
                      {createSelectedGames.map((game, index) => (
                        <div
                          key={game.id}
                          className="h-[62px] rounded-[14px] border border-[#1d293d] bg-[#0f172b] px-3 flex items-center gap-3"
                        >
